scripts.care-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'care-store',
  description:
    "Read and update the care record: medications (meds.json) and the care journal (care.json). Call action:'status' for active meds + upcoming appointments; 'add_med' / 'stop_med' on changes; 'log_entry' for journal notes and symptoms; 'log_appointment' with when (ISO); 'visit_prep' before a doctor visit.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'add_med', 'stop_med', 'log_entry', 'log_appointment', or 'visit_prep'.",
      required: true,
    },
    name: { type: 'string', description: 'Medication name.' },
    dose: { type: 'string', description: "Dose and schedule, e.g. '10mg mornings'." },
    prescriber: { type: 'string', description: 'Who prescribed it.' },
    id: { type: 'string', description: "Medication id, e.g. 'med-2'." },
    kind: { type: 'string', description: "Journal kind: 'note', 'symptom', or 'update'." },
    note: { type: 'string', description: 'The journal entry or appointment description.' },
    when: { type: 'string', description: 'Appointment time (ISO), e.g. 2026-08-02T14:00.' },
  },
  outputs: {
    meds: { type: 'number', description: 'Active medications.' },
    upcoming: { type: 'number', description: 'Upcoming appointments.' },
    summary: { type: 'string', description: 'The care picture (or the visit prep).' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── care-rules-start ──
// Pure derivations: upcoming appointments (journal events kind
// 'appointment' with data.whenAt in the future) and the since-last-visit
// window for visit prep.

function upcomingAppointments(events, nowMs) {
  return events
    .filter(function (e) {
      var when = e.data && typeof e.data.whenAt === 'string' ? Date.parse(e.data.whenAt) : NaN;
      return e.kind === 'appointment' && isFinite(when) && when >= nowMs;
    })
    .sort(function (a, b) {
      return Date.parse(a.data.whenAt) - Date.parse(b.data.whenAt);
    });
}

function lastVisitMs(events, nowMs) {
  var past = events.filter(function (e) {
    var when = e.data && typeof e.data.whenAt === 'string' ? Date.parse(e.data.whenAt) : NaN;
    return e.kind === 'appointment' && isFinite(when) && when < nowMs;
  });
  if (past.length === 0) return null;
  return Math.max.apply(
    null,
    past.map(function (e) {
      return Date.parse(e.data.whenAt);
    }),
  );
}

function sinceWindow(events, nowMs) {
  var last = lastVisitMs(events, nowMs);
  return events.filter(function (e) {
    return e.kind !== 'appointment' && (last === null || Date.parse(e.at) > last);
  });
}
// ── care-rules-end ──

const meds = rosterStore(gezel.fs, 'meds.json', {
  stages: ['active', 'stopped'],
  idPrefix: 'med',
});
const journal = logStore(gezel.fs, 'care.json');

async function resolveMed(): Promise<string> {
  if (input.id) return input.id;
  if (input.name) {
    const wanted = input.name.toLowerCase();
    const matches = (await meds.list({ status: 'active' })).filter(
      (r) => String(r.fields.name ?? '').toLowerCase() === wanted,
    );
    if (matches.length === 1) return matches[0]!.id;
  }
  throw new Error("Pass 'id' (e.g. 'med-2') or an exact active medication 'name'.");
}

if (input.action === 'add_med') {
  if (!input.name || !input.dose) throw new Error("add_med needs 'name' and 'dose'.");
  await meds.add({
    status: 'active',
    fields: {
      name: input.name,
      dose: input.dose,
      ...(input.prescriber ? { prescriber: input.prescriber } : {}),
    },
  });
  await journal.append({ kind: 'update', note: `Started ${input.name} (${input.dose}).` });
} else if (input.action === 'stop_med') {
  const id = await resolveMed();
  const med = await meds.get(id);
  await meds.transition(id, 'stopped', input.note ? { note: input.note } : {});
  await journal.append({
    kind: 'update',
    note: `Stopped ${String(med?.fields.name ?? id)}${input.note ? ` — ${input.note}` : ''}.`,
  });
} else if (input.action === 'log_entry') {
  if (!input.note) throw new Error("log_entry needs 'note'.");
  const kind = input.kind === 'symptom' || input.kind === 'update' ? input.kind : 'note';
  await journal.append({ kind, note: input.note });
} else if (input.action === 'log_appointment') {
  if (!input.note || !input.when) throw new Error("log_appointment needs 'note' and 'when' (ISO).");
  await journal.append({ kind: 'appointment', note: input.note, data: { whenAt: input.when } });
} else if (input.action !== 'status' && input.action !== 'visit_prep') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, add_med, stop_med, log_entry, log_appointment, or visit_prep.`,
  );
}

const activeMeds = await meds.list({ status: 'active' });
const events = await journal.list();
const nowMs = Date.now();
const upcoming = upcomingAppointments(events, nowMs);

let summary: string;
if (input.action === 'visit_prep') {
  const since = sinceWindow(events, nowMs);
  const medLines = activeMeds
    .map((m) => `- ${String(m.fields.name)} ${String(m.fields.dose ?? '')}`.trim())
    .join('\n');
  const noteLines = since
    .map((e) => `- [${e.kind}] ${String(e.at).slice(0, 10)}: ${e.note ?? ''}`)
    .join('\n');
  summary = `VISIT PREP\nActive medications:\n${medLines || '- none recorded'}\nSince the last visit:\n${noteLines || '- quiet — nothing logged'}\nUpcoming:\n${upcoming.map((e) => `- ${String(e.data?.whenAt).slice(0, 16)} ${e.note ?? ''}`).join('\n') || '- none scheduled'}`;
} else {
  const next = upcoming[0];
  summary = `${activeMeds.length} active medication(s). ${upcoming.length} upcoming appointment(s)${
    next ? ` — next: ${String(next.data?.whenAt).slice(0, 16)} ${next.note ?? ''}` : ''
  }. ${events.filter((e) => e.kind !== 'appointment').length} journal entr(ies).`;
}

gezel.output({
  meds: activeMeds.length,
  upcoming: upcoming.length,
  summary,
});

scripts.game-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'game-store',
  description:
    "Read and update the checkers game (game.json). Call action:'board' to see the position, the side to move, and every legal move; action:'ai_move' to play your move (from/to, optional moveThought); action:'state' for a light summary; action:'new_game' to reset, optionally with forceCaptures:false. An illegal ai_move fails with the full legal-move list — pick one of those and call again.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'state', 'board', 'user_move', 'ai_move', or 'new_game'.",
      required: true,
    },
    from: { type: 'string', description: "Origin square, e.g. 'c3'." },
    to: { type: 'string', description: "Destination square (a jump sequence's final square)." },
    moveThought: { type: 'string', description: 'A short line of table talk to show on the board (max 140 chars).' },
    forceCaptures: {
      type: 'boolean',
      description: "For new_game: true for standard forced captures; false to keep ordinary moves legal when a capture is available.",
    },
  },
  outputs: {
    board: { type: 'string', description: 'Legacy human-readable ASCII board with coordinates.' },
    modelState: {
      type: 'object',
      description:
        'Authoritative model-facing state: orientation, square lists, capture availability, and structured legal moves.',
    },
    turn: { type: 'string', description: "Whose move: 'user' or 'ai'." },
    status: { type: 'string', description: 'playing, user_won, or ai_won.' },
    lastMove: { type: 'string', description: "The move just played, e.g. 'c3-d4' or 'b6xd4'." },
    legalMoves: { type: 'string', description: 'Rendered legal moves for the side to move.' },
    captureRule: { type: 'string', description: "Either 'forced' or 'optional'." },
    summary: { type: 'string', description: 'Human-readable game summary.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── checkers-rules-start ──
// Pure, annotation-free rules engine (American/English draughts, 8x8).
// Squares: 64-char row-major string, index = y*8+x, y0 = rank 8, x0 = file a.
// 'r'/'R' = red (the user, moving toward rank 8 / decreasing y);
// 'b'/'B' = black (the AI, moving toward rank 1 / increasing y); '.' empty.
// Kept self-contained between these sentinels so unit tests execute the
// shipped bytes directly (new Function) on every platform.

var FILES = 'abcdefgh';

function sqName(x, y) {
  return FILES[x] + String(8 - y);
}

function parseSq(name) {
  if (typeof name !== 'string' || name.length !== 2) return null;
  var x = FILES.indexOf(name[0].toLowerCase());
  var rank = Number(name[1]);
  if (x < 0 || !(rank >= 1 && rank <= 8)) return null;
  return { x: x, y: 8 - rank };
}

function pieceAt(squares, x, y) {
  return squares[y * 8 + x];
}

function withPiece(squares, x, y, ch) {
  var i = y * 8 + x;
  return squares.slice(0, i) + ch + squares.slice(i + 1);
}

function sideOf(ch) {
  if (ch === 'r' || ch === 'R') return 'user';
  if (ch === 'b' || ch === 'B') return 'ai';
  return null;
}

function isKing(ch) {
  return ch === 'R' || ch === 'B';
}

function kingRowY(side) {
  return side === 'user' ? 0 : 7;
}

function dirsFor(ch) {
  if (isKing(ch)) {
    return [
      { dx: -1, dy: -1 },
      { dx: 1, dy: -1 },
      { dx: -1, dy: 1 },
      { dx: 1, dy: 1 },
    ];
  }
  var dy = ch === 'r' ? -1 : 1;
  return [
    { dx: -1, dy: dy },
    { dx: 1, dy: dy },
  ];
}

function inBounds(x, y) {
  return x >= 0 && x < 8 && y >= 0 && y < 8;
}

function buildInitial() {
  var out = '';
  for (var y = 0; y < 8; y += 1) {
    for (var x = 0; x < 8; x += 1) {
      var dark = (x + y) % 2 === 1;
      if (dark && y <= 2) out += 'b';
      else if (dark && y >= 5) out += 'r';
      else out += '.';
    }
  }
  return out;
}

// All complete jump sequences for the piece at (x, y). A sequence keeps
// jumping with the same piece while another capture is available; a man
// that reaches the king row STOPS there (standard rule — the move ends on
// crowning). Each result: { from, to, path, captures } (square names).
function jumpSequencesFrom(squares, x, y, ch) {
  var side = sideOf(ch);
  var results = [];

  function explore(sq, cx, cy, curCh, path, captures) {
    var extended = false;
    var dirs = dirsFor(curCh);
    for (var i = 0; i < dirs.length; i += 1) {
      var mx = cx + dirs[i].dx;
      var my = cy + dirs[i].dy;
      var lx = cx + dirs[i].dx * 2;
      var ly = cy + dirs[i].dy * 2;
      if (!inBounds(lx, ly)) continue;
      var mid = pieceAt(sq, mx, my);
      if (sideOf(mid) === null || sideOf(mid) === side) continue;
      if (pieceAt(sq, lx, ly) !== '.') continue;

      var nextCh = curCh;
      var crowned = false;
      if (!isKing(curCh) && ly === kingRowY(side)) {
        nextCh = side === 'user' ? 'R' : 'B';
        crowned = true;
      }
      var nextSq = withPiece(withPiece(withPiece(sq, cx, cy, '.'), mx, my, '.'), lx, ly, nextCh);
      var nextPath = path.concat([sqName(lx, ly)]);
      var nextCaptures = captures.concat([sqName(mx, my)]);
      extended = true;
      if (crowned) {
        results.push({
          from: path[0],
          to: sqName(lx, ly),
          path: nextPath,
          captures: nextCaptures,
        });
      } else {
        explore(nextSq, lx, ly, nextCh, nextPath, nextCaptures);
      }
    }
    if (!extended && captures.length > 0) {
      results.push({ from: path[0], to: path[path.length - 1], path: path, captures: captures });
    }
  }

  explore(squares, x, y, ch, [sqName(x, y)], []);
  return results;
}

// Every legal move for `side`. With standard forced captures, any jump
// masks quiet moves. In the optional-capture variant, both remain legal.
// Simple moves are single diagonal steps.
function legalMovesFor(squares, side, forceCaptures) {
  var jumps = [];
  var steps = [];
  for (var y = 0; y < 8; y += 1) {
    for (var x = 0; x < 8; x += 1) {
      var ch = pieceAt(squares, x, y);
      if (sideOf(ch) !== side) continue;
      var seqs = jumpSequencesFrom(squares, x, y, ch);
      for (var j = 0; j < seqs.length; j += 1) jumps.push(seqs[j]);
      var dirs = dirsFor(ch);
      for (var i = 0; i < dirs.length; i += 1) {
        var nx = x + dirs[i].dx;
        var ny = y + dirs[i].dy;
        if (!inBounds(nx, ny) || pieceAt(squares, nx, ny) !== '.') continue;
        steps.push({
          from: sqName(x, y),
          to: sqName(nx, ny),
          path: [sqName(x, y), sqName(nx, ny)],
          captures: [],
        });
      }
    }
  }
  return forceCaptures !== false && jumps.length > 0 ? jumps : jumps.concat(steps);
}

// Apply a legal sequence, returning the new squares string. Crowns a man
// that ends on the king row (mid-sequence crowning already ended the
// sequence in jumpSequencesFrom, so end-of-path crowning is complete).
function applySequence(squares, seq) {
  var start = parseSq(seq.from);
  var end = parseSq(seq.to);
  var ch = pieceAt(squares, start.x, start.y);
  var side = sideOf(ch);
  var next = withPiece(squares, start.x, start.y, '.');
  for (var i = 0; i < seq.captures.length; i += 1) {
    var cap = parseSq(seq.captures[i]);
    next = withPiece(next, cap.x, cap.y, '.');
  }
  var finalCh = ch;
  if (!isKing(ch) && end.y === kingRowY(side)) finalCh = side === 'user' ? 'R' : 'B';
  return withPiece(next, end.x, end.y, finalCh);
}

// The side to move with no legal move has lost (covers zero pieces too).
function statusAfter(squares, sideToMove, forceCaptures) {
  if (legalMovesFor(squares, sideToMove, forceCaptures).length > 0) return 'playing';
  return sideToMove === 'user' ? 'ai_won' : 'user_won';
}

function describeMove(seq) {
  var joiner = seq.captures.length > 0 ? 'x' : '-';
  var text = seq.path.join(joiner);
  if (seq.captures.length > 0) text += ' (captures ' + seq.captures.join(', ') + ')';
  return text;
}

function renderAscii(squares) {
  var lines = ['  a b c d e f g h'];
  for (var y = 0; y < 8; y += 1) {
    var row = String(8 - y);
    for (var x = 0; x < 8; x += 1) {
      row += ' ' + pieceAt(squares, x, y);
    }
    lines.push(row);
  }
  lines.push('r/R = red (your opponent, moving up). b/B = black (you, moving down). Capitals are kings.');
  return lines.join('\n');
}

function renderPieces(squares) {
  var redMen = [];
  var redKings = [];
  var blackMen = [];
  var blackKings = [];
  for (var y = 0; y < 8; y += 1) {
    for (var x = 0; x < 8; x += 1) {
      var ch = pieceAt(squares, x, y);
      var name = sqName(x, y);
      if (ch === 'r') redMen.push(name);
      else if (ch === 'R') redKings.push(name);
      else if (ch === 'b') blackMen.push(name);
      else if (ch === 'B') blackKings.push(name);
    }
  }
  return { redMen: redMen, redKings: redKings, blackMen: blackMen, blackKings: blackKings };
}
// ── checkers-rules-end ──

const STATE_FILE = 'game.json';
const STAGE_SIDES = { user: 'red', ai: 'black' };

interface GameState {
  version: number;
  squares: string;
  turn: 'user' | 'ai';
  status: 'playing' | 'user_won' | 'ai_won' | 'draw';
  userColor: string;
  forceCaptures: boolean;
  legalMoves: Array<{ from: string; to: string; path: string[]; captures: string[] }>;
  moveLog: Array<{
    by: 'user' | 'ai';
    from: string;
    to: string;
    captures: string[];
    at: string;
    moveThought?: string;
  }>;
  lastMove: { by: 'user' | 'ai'; from: string; to: string; captures: string[] } | null;
  lastMoveThought: string;
  updatedAt: string;
}

function freshState(forceCaptures = true): GameState {
  const squares = buildInitial();
  return {
    version: 1,
    squares,
    turn: 'user',
    status: 'playing',
    userColor: 'red',
    forceCaptures,
    legalMoves: legalMovesFor(squares, 'user', forceCaptures),
    moveLog: [],
    lastMove: null,
    lastMoveThought: '',
    updatedAt: new Date().toISOString(),
  };
}

async function load(): Promise<GameState> {
  let raw: string;
  try {
    raw = await gezel.fs.read(STATE_FILE);
  } catch {
    return freshState();
  }
  const parsed = JSON.parse(raw) as Partial<GameState>;
  if (typeof parsed.squares !== 'string' || parsed.squares.length !== 64) {
    throw new Error(`${STATE_FILE} is corrupt (squares missing); call action:'new_game' to reset.`);
  }
  return { ...freshState(parsed.forceCaptures !== false), ...parsed, forceCaptures: parsed.forceCaptures !== false } as GameState;
}

async function persist(state: GameState): Promise<GameState> {
  state.legalMoves = state.status === 'playing' ? legalMovesFor(state.squares, state.turn, state.forceCaptures) : [];
  state.updatedAt = new Date().toISOString();
  await gezel.fs.write(STATE_FILE, `${JSON.stringify(state, null, 2)}\n`);
  return state;
}

function summarize(state: GameState): string {
  const counts = { r: 0, b: 0 };
  for (const ch of state.squares) {
    if (ch === 'r' || ch === 'R') counts.r += 1;
    if (ch === 'b' || ch === 'B') counts.b += 1;
  }
  if (state.status === 'user_won') return `Game over — the user (red) won. Red ${counts.r} pieces, black ${counts.b}.`;
  if (state.status === 'ai_won') return `Game over — you (black) won. Red ${counts.r} pieces, black ${counts.b}.`;
  return `Move ${state.moveLog.length + 1}: ${STAGE_SIDES[state.turn]} (${state.turn}) to move. Red ${counts.r} pieces, black ${counts.b}. Captures are ${state.forceCaptures ? 'forced' : 'optional'}.`;
}

function renderLegal(state: GameState): string {
  if (state.status !== 'playing') return '(game over)';
  return state.legalMoves.map(describeMove).join(', ') || '(none)';
}

function renderModelState(state: GameState) {
  return {
    status: state.status,
    sideToMove: STAGE_SIDES[state.turn],
    coordinateFormat: 'file-rank (for example e3)',
    orientation: { redForwardRankDelta: 1, blackForwardRankDelta: -1 },
    pieces: renderPieces(state.squares),
    capturePolicy: state.forceCaptures ? 'mandatory-if-available' : 'optional',
    capturesAvailable: state.legalMoves.some((move) => move.captures.length > 0),
    legalMoves: state.legalMoves.map((move) => ({
      from: move.from,
      to: move.to,
      path: move.path,
      captures: move.captures,
      type: move.captures.length > 0 ? 'capture' : 'step',
    })),
  };
}

function applyTurn(state: GameState, by: 'user' | 'ai', moveThought?: string): GameState {
  if (state.status !== 'playing') {
    throw new Error(`The game is over (${state.status}). Call action:'new_game' to start another.`);
  }
  if (state.turn !== by) {
    throw new Error(
      by === 'ai'
        ? "It's not your turn — the user has not moved yet."
        : "It's not your turn — the AI is still to move.",
    );
  }
  if (!input.from || !input.to) throw new Error("Pass 'from' and 'to' squares, e.g. from:'c3' to:'d4'.");
  const seq = state.legalMoves.find(
    (m) => m.from === input.from!.toLowerCase() && m.to === input.to!.toLowerCase(),
  );
  if (!seq) {
    throw new Error(
      `Illegal move ${input.from}-${input.to}. Legal moves for ${STAGE_SIDES[by]}: ${renderLegal(state)}`,
    );
  }
  state.squares = applySequence(state.squares, seq);
  const nextTurn = by === 'user' ? 'ai' : 'user';
  state.status = statusAfter(state.squares, nextTurn, state.forceCaptures) as GameState['status'];
  state.turn = nextTurn;
  const entry = {
    by,
    from: seq.from,
    to: seq.to,
    captures: seq.captures,
    at: new Date().toISOString(),
    ...(moveThought ? { moveThought } : {}),
  };
  state.moveLog.push(entry);
  state.lastMove = { by, from: seq.from, to: seq.to, captures: seq.captures };
  if (by === 'ai' && moveThought) state.lastMoveThought = moveThought;
  return state;
}

let state = await load();
let lastMoveText = state.lastMove
  ? describeMove({ ...state.lastMove, path: [state.lastMove.from, state.lastMove.to] })
  : '(none)';

if (input.action === 'new_game') {
  state = await persist(freshState(input.forceCaptures !== false));
  lastMoveText = '(none)';
} else if (input.action === 'user_move' || input.action === 'ai_move') {
  const by = input.action === 'user_move' ? 'user' : 'ai';
  const moveThought = input.moveThought ? input.moveThought.trim().slice(0, 140) : undefined;
  const before = state.legalMoves.find(
    (m) => m.from === (input.from ?? '').toLowerCase() && m.to === (input.to ?? '').toLowerCase(),
  );
  applyTurn(state, by, moveThought);
  state = await persist(state);
  lastMoveText = before ? describeMove(before) : `${input.from}-${input.to}`;
} else if (input.action !== 'state' && input.action !== 'board') {
  throw new Error(`Unknown action '${input.action}'. Use state, board, user_move, ai_move, or new_game.`);
}

gezel.output({
  board:
    input.action === 'state'
      ? `${renderAscii(state.squares).split('\n').slice(0, 9).join('\n')}`
      : `${renderAscii(state.squares)}\nCapture rule: ${state.forceCaptures ? 'forced' : 'optional'}.\nTurn: ${STAGE_SIDES[state.turn]} (${state.turn}). Legal moves: ${renderLegal(state)}`,
  modelState: renderModelState(state),
  turn: state.turn,
  status: state.status,
  lastMove: lastMoveText,
  legalMoves: renderLegal(state),
  captureRule: state.forceCaptures ? 'forced' : 'optional',
  summary: summarize(state),
});

import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'game-store',
  description:
    "Read and update the chess game (game.json). Call action:'board' to see the position and every legal move; action:'ai_move' to play your move (from/to, optional promotion and moveThought); action:'state' for a light summary; action:'new_game' to reset. Illegal moves fail with the engine's legal-move list.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'state', 'board', 'user_move', 'ai_move', or 'new_game'.",
      required: true,
    },
    from: { type: 'string', description: "Origin square, e.g. 'e7'." },
    to: { type: 'string', description: "Destination square, e.g. 'e5'." },
    promotion: {
      type: 'string',
      description: "Promotion piece: 'q', 'r', 'b', or 'n'. Defaults to queen.",
    },
    moveThought: {
      type: 'string',
      description: 'A short line of table talk to show on the board (max 140 chars).',
    },
  },
  outputs: {
    board: { type: 'string', description: 'ASCII board with coordinates.' },
    turn: { type: 'string', description: "Whose move: 'user' (white) or 'ai' (black)." },
    status: {
      type: 'string',
      description: 'playing, user_won, ai_won, or draw.',
    },
    lastMove: { type: 'string', description: "The move just played, e.g. 'e2-e4'." },
    legalMoves: { type: 'string', description: 'Rendered legal moves for the side to move.' },
    summary: { type: 'string', description: 'Human-readable game summary.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── chess-rules-start ──
// Pure, annotation-free chess engine. Squares are a 64-character row-major
// string: y0 is rank 8, x0 is file a. Uppercase pieces are white (the user);
// lowercase pieces are black (the AI).

var FILES = 'abcdefgh';
var PROMOTIONS = ['q', 'r', 'b', 'n'];

function sqName(x, y) {
  return FILES[x] + String(8 - y);
}

function parseSq(name) {
  if (typeof name !== 'string' || name.length !== 2) return null;
  var x = FILES.indexOf(name[0].toLowerCase());
  var rank = Number(name[1]);
  if (x < 0 || !(rank >= 1 && rank <= 8)) return null;
  return { x: x, y: 8 - rank };
}

function inBounds(x, y) {
  return x >= 0 && x < 8 && y >= 0 && y < 8;
}

function pieceAt(squares, x, y) {
  return squares[y * 8 + x];
}

function withPiece(squares, x, y, ch) {
  var i = y * 8 + x;
  return squares.slice(0, i) + ch + squares.slice(i + 1);
}

function sideOf(ch) {
  if (!ch || ch === '.') return null;
  return ch === ch.toUpperCase() ? 'user' : 'ai';
}

function otherSide(side) {
  return side === 'user' ? 'ai' : 'user';
}

function kindOf(ch) {
  return ch && ch !== '.' ? ch.toLowerCase() : '';
}

function buildInitial() {
  return 'rnbqkbnr' + 'pppppppp' + '.'.repeat(32) + 'PPPPPPPP' + 'RNBQKBNR';
}

function findKing(squares, side) {
  var needle = side === 'user' ? 'K' : 'k';
  var i = squares.indexOf(needle);
  return i < 0 ? null : { x: i % 8, y: Math.floor(i / 8) };
}

function isAttacked(squares, x, y, bySide) {
  var pawn = bySide === 'user' ? 'P' : 'p';
  var pawnY = y - (bySide === 'user' ? -1 : 1);
  for (var pdx of [-1, 1]) {
    var px = x - pdx;
    if (inBounds(px, pawnY) && pieceAt(squares, px, pawnY) === pawn) return true;
  }

  var knight = bySide === 'user' ? 'N' : 'n';
  var knightSteps = [
    [-2, -1],
    [-2, 1],
    [-1, -2],
    [-1, 2],
    [1, -2],
    [1, 2],
    [2, -1],
    [2, 1],
  ];
  for (var n of knightSteps) {
    if (inBounds(x + n[0], y + n[1]) && pieceAt(squares, x + n[0], y + n[1]) === knight) {
      return true;
    }
  }

  var rays = [
    [-1, 0, 'rq'],
    [1, 0, 'rq'],
    [0, -1, 'rq'],
    [0, 1, 'rq'],
    [-1, -1, 'bq'],
    [-1, 1, 'bq'],
    [1, -1, 'bq'],
    [1, 1, 'bq'],
  ];
  for (var ray of rays) {
    var rx = x + ray[0];
    var ry = y + ray[1];
    while (inBounds(rx, ry)) {
      var seen = pieceAt(squares, rx, ry);
      if (seen !== '.') {
        if (sideOf(seen) === bySide && ray[2].indexOf(kindOf(seen)) >= 0) return true;
        break;
      }
      rx += ray[0];
      ry += ray[1];
    }
  }

  var king = bySide === 'user' ? 'K' : 'k';
  for (var ky = -1; ky <= 1; ky += 1) {
    for (var kx = -1; kx <= 1; kx += 1) {
      if (
        (kx !== 0 || ky !== 0) &&
        inBounds(x + kx, y + ky) &&
        pieceAt(squares, x + kx, y + ky) === king
      ) {
        return true;
      }
    }
  }
  return false;
}

function inCheck(squares, side) {
  var king = findKing(squares, side);
  return !king || isAttacked(squares, king.x, king.y, otherSide(side));
}

function pushMove(out, fromX, fromY, toX, toY, extra) {
  out.push(
    Object.assign(
      {
        from: sqName(fromX, fromY),
        to: sqName(toX, toY),
        capture: false,
      },
      extra || {},
    ),
  );
}

function pseudoMovesFor(squares, side, castling, enPassant) {
  var out = [];
  for (var y = 0; y < 8; y += 1) {
    for (var x = 0; x < 8; x += 1) {
      var ch = pieceAt(squares, x, y);
      if (sideOf(ch) !== side) continue;
      var kind = kindOf(ch);

      if (kind === 'p') {
        var dir = side === 'user' ? -1 : 1;
        var startY = side === 'user' ? 6 : 1;
        var promotionY = side === 'user' ? 0 : 7;
        var oneY = y + dir;
        if (inBounds(x, oneY) && pieceAt(squares, x, oneY) === '.') {
          if (oneY === promotionY) {
            for (var promotion of PROMOTIONS) {
              pushMove(out, x, y, x, oneY, { promotion: promotion });
            }
          } else {
            pushMove(out, x, y, x, oneY);
            var twoY = y + dir * 2;
            if (y === startY && pieceAt(squares, x, twoY) === '.') {
              pushMove(out, x, y, x, twoY, { doublePawn: true });
            }
          }
        }
        for (var dx of [-1, 1]) {
          var cx = x + dx;
          var cy = y + dir;
          if (!inBounds(cx, cy)) continue;
          var target = pieceAt(squares, cx, cy);
          var targetName = sqName(cx, cy);
          var isEp = targetName === enPassant && target === '.';
          if ((target !== '.' && sideOf(target) === otherSide(side)) || isEp) {
            if (cy === promotionY) {
              for (var capturePromotion of PROMOTIONS) {
                pushMove(out, x, y, cx, cy, {
                  capture: true,
                  promotion: capturePromotion,
                  enPassant: isEp,
                });
              }
            } else {
              pushMove(out, x, y, cx, cy, { capture: true, enPassant: isEp });
            }
          }
        }
        continue;
      }

      if (kind === 'n') {
        var jumps = [
          [-2, -1],
          [-2, 1],
          [-1, -2],
          [-1, 2],
          [1, -2],
          [1, 2],
          [2, -1],
          [2, 1],
        ];
        for (var jump of jumps) {
          var nx = x + jump[0];
          var ny = y + jump[1];
          if (!inBounds(nx, ny) || sideOf(pieceAt(squares, nx, ny)) === side) continue;
          pushMove(out, x, y, nx, ny, { capture: pieceAt(squares, nx, ny) !== '.' });
        }
        continue;
      }

      if (kind === 'b' || kind === 'r' || kind === 'q') {
        var dirs = [];
        if (kind === 'b' || kind === 'q') dirs.push([-1, -1], [-1, 1], [1, -1], [1, 1]);
        if (kind === 'r' || kind === 'q') dirs.push([-1, 0], [1, 0], [0, -1], [0, 1]);
        for (var d of dirs) {
          var sx = x + d[0];
          var sy = y + d[1];
          while (inBounds(sx, sy)) {
            var occupant = pieceAt(squares, sx, sy);
            if (sideOf(occupant) === side) break;
            pushMove(out, x, y, sx, sy, { capture: occupant !== '.' });
            if (occupant !== '.') break;
            sx += d[0];
            sy += d[1];
          }
        }
        continue;
      }

      if (kind === 'k') {
        for (var kdy = -1; kdy <= 1; kdy += 1) {
          for (var kdx = -1; kdx <= 1; kdx += 1) {
            if (kdx === 0 && kdy === 0) continue;
            var ktx = x + kdx;
            var kty = y + kdy;
            if (!inBounds(ktx, kty) || sideOf(pieceAt(squares, ktx, kty)) === side) continue;
            pushMove(out, x, y, ktx, kty, { capture: pieceAt(squares, ktx, kty) !== '.' });
          }
        }

        var homeY = side === 'user' ? 7 : 0;
        var kingChar = side === 'user' ? 'K' : 'k';
        var rookChar = side === 'user' ? 'R' : 'r';
        var enemy = otherSide(side);
        if (x === 4 && y === homeY && ch === kingChar && !isAttacked(squares, 4, homeY, enemy)) {
          var kingRight = side === 'user' ? castling.indexOf('K') >= 0 : castling.indexOf('k') >= 0;
          if (
            kingRight &&
            pieceAt(squares, 7, homeY) === rookChar &&
            pieceAt(squares, 5, homeY) === '.' &&
            pieceAt(squares, 6, homeY) === '.' &&
            !isAttacked(squares, 5, homeY, enemy) &&
            !isAttacked(squares, 6, homeY, enemy)
          ) {
            pushMove(out, x, y, 6, homeY, { castle: 'king' });
          }
          var queenRight = side === 'user' ? castling.indexOf('Q') >= 0 : castling.indexOf('q') >= 0;
          if (
            queenRight &&
            pieceAt(squares, 0, homeY) === rookChar &&
            pieceAt(squares, 1, homeY) === '.' &&
            pieceAt(squares, 2, homeY) === '.' &&
            pieceAt(squares, 3, homeY) === '.' &&
            !isAttacked(squares, 3, homeY, enemy) &&
            !isAttacked(squares, 2, homeY, enemy)
          ) {
            pushMove(out, x, y, 2, homeY, { castle: 'queen' });
          }
        }
      }
    }
  }
  return out;
}

function applyUnchecked(squares, move, side) {
  var from = parseSq(move.from);
  var to = parseSq(move.to);
  var ch = pieceAt(squares, from.x, from.y);
  var next = withPiece(squares, from.x, from.y, '.');
  if (move.enPassant) {
    next = withPiece(next, to.x, from.y, '.');
  }
  if (move.castle === 'king') {
    next = withPiece(next, 7, from.y, '.');
    next = withPiece(next, 5, from.y, side === 'user' ? 'R' : 'r');
  } else if (move.castle === 'queen') {
    next = withPiece(next, 0, from.y, '.');
    next = withPiece(next, 3, from.y, side === 'user' ? 'R' : 'r');
  }
  if (move.promotion) ch = side === 'user' ? move.promotion.toUpperCase() : move.promotion;
  return withPiece(next, to.x, to.y, ch);
}

function legalMovesFor(squares, side, castling, enPassant) {
  return pseudoMovesFor(squares, side, castling || '', enPassant || null).filter(function (move) {
    return !inCheck(applyUnchecked(squares, move, side), side);
  });
}

function nextCastling(castling, squares, move) {
  var rights = castling || '';
  var ch = pieceAt(squares, parseSq(move.from).x, parseSq(move.from).y);
  if (ch === 'K') rights = rights.replace(/K|Q/g, '');
  if (ch === 'k') rights = rights.replace(/k|q/g, '');
  if (move.from === 'a1' || move.to === 'a1') rights = rights.replace('Q', '');
  if (move.from === 'h1' || move.to === 'h1') rights = rights.replace('K', '');
  if (move.from === 'a8' || move.to === 'a8') rights = rights.replace('q', '');
  if (move.from === 'h8' || move.to === 'h8') rights = rights.replace('k', '');
  return rights;
}

function nextEnPassant(move, side) {
  if (!move.doublePawn) return null;
  var from = parseSq(move.from);
  var to = parseSq(move.to);
  return sqName(from.x, (from.y + to.y) / 2);
}

function isInsufficientMaterial(squares) {
  var pieces = [];
  for (var i = 0; i < squares.length; i += 1) {
    var ch = squares[i];
    if (ch !== '.' && kindOf(ch) !== 'k') pieces.push({ ch: ch, x: i % 8, y: Math.floor(i / 8) });
  }
  if (pieces.length === 0) return true;
  if (pieces.length === 1 && (kindOf(pieces[0].ch) === 'b' || kindOf(pieces[0].ch) === 'n')) {
    return true;
  }
  if (
    pieces.length > 0 &&
    pieces.every(function (p) {
      return kindOf(p.ch) === 'b';
    })
  ) {
    var color = (pieces[0].x + pieces[0].y) % 2;
    return pieces.every(function (p) {
      return (p.x + p.y) % 2 === color;
    });
  }
  return false;
}

function positionKey(squares, side, castling, enPassant) {
  var effectiveEnPassant =
    enPassant &&
    legalMovesFor(squares, side, castling, enPassant).some(function (move) {
      return move.enPassant;
    })
      ? enPassant
      : '-';
  return [squares, side, castling || '-', effectiveEnPassant].join('|');
}

function statusAfter(squares, sideToMove, castling, enPassant) {
  if (isInsufficientMaterial(squares)) return 'draw';
  var moves = legalMovesFor(squares, sideToMove, castling, enPassant);
  if (moves.length > 0) return 'playing';
  if (!inCheck(squares, sideToMove)) return 'draw';
  return sideToMove === 'user' ? 'ai_won' : 'user_won';
}

function describeMove(move) {
  if (move.castle === 'king') return move.from + '-' + move.to + ' (O-O)';
  if (move.castle === 'queen') return move.from + '-' + move.to + ' (O-O-O)';
  var text = move.from + (move.capture ? 'x' : '-') + move.to;
  if (move.promotion) text += '=' + move.promotion.toUpperCase();
  if (move.enPassant) text += ' e.p.';
  return text;
}

function renderAscii(squares) {
  var lines = ['  a b c d e f g h'];
  for (var y = 0; y < 8; y += 1) {
    var row = String(8 - y);
    for (var x = 0; x < 8; x += 1) row += ' ' + pieceAt(squares, x, y);
    lines.push(row + ' ' + String(8 - y));
  }
  lines.push('  a b c d e f g h');
  lines.push('Uppercase = white (user). Lowercase = black (you).');
  return lines.join('\n');
}
// ── chess-rules-end ──

const STATE_FILE = 'game.json';
const SIDE_NAMES = { user: 'white', ai: 'black' };

interface ChessMove {
  from: string;
  to: string;
  capture: boolean;
  promotion?: string;
  doublePawn?: boolean;
  enPassant?: boolean;
  castle?: string;
}

interface GameState {
  version: number;
  squares: string;
  turn: 'user' | 'ai';
  status: 'playing' | 'user_won' | 'ai_won' | 'draw';
  castling: string;
  enPassant: string | null;
  halfmoveClock: number;
  fullmoveNumber: number;
  positionHistory: string[];
  legalMoves: ChessMove[];
  moveLog: Array<{
    by: 'user' | 'ai';
    from: string;
    to: string;
    promotion?: string;
    notation: string;
    at: string;
    moveThought?: string;
  }>;
  lastMove: {
    by: 'user' | 'ai';
    from: string;
    to: string;
    promotion?: string;
    notation: string;
  } | null;
  lastMoveThought: string;
  updatedAt: string;
}

function freshState(): GameState {
  const squares = buildInitial();
  const castling = 'KQkq';
  return {
    version: 1,
    squares,
    turn: 'user',
    status: 'playing',
    castling,
    enPassant: null,
    halfmoveClock: 0,
    fullmoveNumber: 1,
    positionHistory: [positionKey(squares, 'user', castling, null)],
    legalMoves: legalMovesFor(squares, 'user', castling, null),
    moveLog: [],
    lastMove: null,
    lastMoveThought: '',
    updatedAt: new Date().toISOString(),
  };
}

async function load(): Promise<GameState> {
  let raw: string;
  try {
    raw = await gezel.fs.read(STATE_FILE);
  } catch {
    return freshState();
  }
  const parsed = JSON.parse(raw) as Partial<GameState>;
  if (typeof parsed.squares !== 'string' || parsed.squares.length !== 64) {
    throw new Error(`${STATE_FILE} is corrupt; call action:'new_game' to reset.`);
  }
  return {
    ...freshState(),
    ...parsed,
    castling: typeof parsed.castling === 'string' ? parsed.castling : '',
    enPassant: parsed.enPassant ?? null,
  } as GameState;
}

async function persist(state: GameState): Promise<GameState> {
  state.legalMoves =
    state.status === 'playing'
      ? legalMovesFor(state.squares, state.turn, state.castling, state.enPassant)
      : [];
  state.updatedAt = new Date().toISOString();
  await gezel.fs.write(STATE_FILE, `${JSON.stringify(state, null, 2)}\n`);
  return state;
}

function renderLegal(state: GameState): string {
  if (state.status !== 'playing') return '(game over)';
  return state.legalMoves.map(describeMove).join(', ') || '(none)';
}

function summarize(state: GameState): string {
  if (state.status === 'user_won') return 'Checkmate — the user (white) won.';
  if (state.status === 'ai_won') return 'Checkmate — you (black) won.';
  if (state.status === 'draw') return 'Game over — draw.';
  const check = inCheck(state.squares, state.turn) ? ' The king is in check.' : '';
  return `Move ${state.fullmoveNumber}: ${SIDE_NAMES[state.turn]} (${state.turn}) to move.${check}`;
}

function applyTurn(
  state: GameState,
  by: 'user' | 'ai',
  moveThought?: string,
): { state: GameState; move: ChessMove } {
  if (state.status !== 'playing') {
    throw new Error(`The game is over (${state.status}). Call action:'new_game' to start another.`);
  }
  if (state.turn !== by) {
    throw new Error(by === 'ai' ? "It's not your turn yet." : 'The opponent is still to move.');
  }
  if (!input.from || !input.to) throw new Error("Pass 'from' and 'to' squares.");
  const wantedPromotion = (input.promotion || 'q').toLowerCase();
  const candidates = state.legalMoves.filter(
    (move) =>
      move.from === input.from!.toLowerCase() &&
      move.to === input.to!.toLowerCase(),
  );
  const move =
    candidates.find((candidate) => (candidate.promotion || 'q') === wantedPromotion) ??
    candidates.find((candidate) => !candidate.promotion);
  if (!move) {
    throw new Error(
      `Illegal move ${input.from}-${input.to}. Legal moves for ${SIDE_NAMES[by]}: ${renderLegal(state)}`,
    );
  }

  const movingPiece = pieceAt(
    state.squares,
    parseSq(move.from)!.x,
    parseSq(move.from)!.y,
  );
  const oldSquares = state.squares;
  state.castling = nextCastling(state.castling, oldSquares, move);
  state.squares = applyUnchecked(oldSquares, move, by);
  state.enPassant = nextEnPassant(move, by);
  state.halfmoveClock =
    kindOf(movingPiece) === 'p' || move.capture ? 0 : state.halfmoveClock + 1;
  if (by === 'ai') state.fullmoveNumber += 1;
  state.turn = otherSide(by) as 'user' | 'ai';
  const key = positionKey(state.squares, state.turn, state.castling, state.enPassant);
  state.positionHistory.push(key);
  state.status = statusAfter(
    state.squares,
    state.turn,
    state.castling,
    state.enPassant,
  ) as GameState['status'];
  if (
    state.status === 'playing' &&
    (state.halfmoveClock >= 100 ||
      state.positionHistory.filter((candidate) => candidate === key).length >= 3)
  ) {
    state.status = 'draw';
  }

  const notation = describeMove(move);
  const entry = {
    by,
    from: move.from,
    to: move.to,
    ...(move.promotion ? { promotion: move.promotion } : {}),
    notation,
    at: new Date().toISOString(),
    ...(moveThought ? { moveThought } : {}),
  };
  state.moveLog.push(entry);
  state.lastMove = {
    by,
    from: move.from,
    to: move.to,
    ...(move.promotion ? { promotion: move.promotion } : {}),
    notation,
  };
  if (by === 'ai' && moveThought) state.lastMoveThought = moveThought;
  return { state, move };
}

let state = await load();
let lastMoveText = state.lastMove?.notation ?? '(none)';

if (input.action === 'new_game') {
  state = await persist(freshState());
  lastMoveText = '(none)';
} else if (input.action === 'user_move' || input.action === 'ai_move') {
  const by = input.action === 'user_move' ? 'user' : 'ai';
  const moveThought = input.moveThought?.trim().slice(0, 140);
  const applied = applyTurn(state, by, moveThought);
  state = await persist(applied.state);
  lastMoveText = describeMove(applied.move);
} else if (input.action !== 'state' && input.action !== 'board') {
  throw new Error(`Unknown action '${input.action}'. Use state, board, user_move, ai_move, or new_game.`);
}

gezel.output({
  board:
    `${renderAscii(state.squares)}\nTurn: ${SIDE_NAMES[state.turn]} (${state.turn}).` +
    `${inCheck(state.squares, state.turn) && state.status === 'playing' ? ' CHECK.' : ''}\n` +
    `Legal moves: ${renderLegal(state)}`,
  turn: state.turn,
  status: state.status,
  lastMove: lastMoveText,
  legalMoves: renderLegal(state),
  summary: summarize(state),
});

scripts.scheme-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'scheme-store',
  description:
    "Save and list the project's design color schemes. Call action:'save' with a name and an array of hex colors to add a scheme (it lands in artifacts/schemes/ and shows on the project's gallery). Call action:'list' to see what's saved.",
  inputs: {
    action: { type: 'string', description: "'save' or 'list'.", required: true },
    name: { type: 'string', description: "Scheme name (required for 'save'), e.g. 'Dusk'." },
    colors: {
      type: 'json',
      description: "Array of hex colors for 'save', e.g. [\"#1b1a2e\", \"#e0894a\", \"#f5f0e8\"].",
    },
  },
  outputs: {
    count: { type: 'number', description: 'How many schemes are saved.' },
    message: { type: 'string', description: 'Human-readable summary.' },
  },
  requires: ['artifacts.read', 'artifacts.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

interface Scheme {
  name: string;
  file: string;
  colors: string[];
}

const INDEX = 'schemes/index.json';

async function loadIndex(): Promise<Scheme[]> {
  try {
    const raw = await gezel.artifacts.read(INDEX);
    const parsed = JSON.parse(raw) as { schemes?: Scheme[] };
    return Array.isArray(parsed.schemes) ? parsed.schemes : [];
  } catch {
    return [];
  }
}

function slugify(s: string): string {
  return (
    s
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '') || 'scheme'
  );
}

const schemes = await loadIndex();

if (input.action === 'save') {
  const name = (input.name ?? '').trim();
  const colors = Array.isArray(input.colors) ? input.colors.map(String) : [];
  if (!name || colors.length === 0) {
    gezel.output({ count: schemes.length, message: 'save needs a name and a non-empty colors array.' });
  } else {
    const file = `schemes/${slugify(name)}.json`;
    await gezel.artifacts.write(file, `${JSON.stringify({ name, colors }, null, 2)}\n`);
    const next = [...schemes.filter((s) => s.file !== file), { name, file, colors }];
    await gezel.artifacts.write(INDEX, `${JSON.stringify({ schemes: next }, null, 2)}\n`);
    gezel.output({ count: next.length, message: `Saved "${name}" (${colors.length} colors). ${next.length} scheme(s) total.` });
  }
} else {
  gezel.output({
    count: schemes.length,
    message: schemes.length
      ? `${schemes.length} scheme(s): ${schemes.map((s) => s.name).join(', ')}.`
      : 'No schemes saved yet.',
  });
}

scripts.event-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { ledgerStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'event-store',
  description:
    "Read and update the event: guests (guests.json) and spending (budget.json). Call action:'status' for headcount + budget + countdown; 'add_guest' as invitations go out; 'guest_status' as RSVPs land (invited/yes/no); 'record_spend' when money is committed (ordinary units); 'guest_list' to read everyone.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'add_guest', 'guest_status', 'record_spend', or 'guest_list'.",
      required: true,
    },
    name: { type: 'string', description: 'Guest name (party name is fine).' },
    party: { type: 'number', description: 'How many people this entry covers (default 1).' },
    status: { type: 'string', description: "RSVP status: 'invited', 'yes', or 'no'." },
    id: { type: 'string', description: "Guest id, e.g. 'guest-4'." },
    amount: { type: 'number', description: 'Spend amount in ordinary units.' },
    category: { type: 'string', description: "Spend category, e.g. 'venue', 'catering'." },
    note: { type: 'string', description: 'Short note.' },
  },
  outputs: {
    invited: { type: 'number', description: 'People invited (sum of parties).' },
    coming: { type: 'number', description: "People who said yes." },
    spentCents: { type: 'number', description: 'Total committed spend, in cents.' },
    summary: { type: 'string', description: 'The event picture.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── event-rules-start ──
// Pure derivations: headcounts weighted by party size, and the countdown.

function toCents(amount) {
  if (typeof amount !== 'number' || !isFinite(amount) || amount <= 0) return null;
  return Math.round(amount * 100);
}

function fmtCents(cents) {
  var abs = Math.abs(cents);
  return (cents < 0 ? '-' : '') + Math.floor(abs / 100) + '.' + String(abs % 100).padStart(2, '0');
}

function partyOf(record) {
  var p = record.fields && record.fields.party;
  return typeof p === 'number' && p >= 1 ? Math.floor(p) : 1;
}

function headcounts(records) {
  var invited = 0;
  var coming = 0;
  var awaiting = 0;
  records.forEach(function (r) {
    var size = partyOf(r);
    invited += size;
    if (r.status === 'yes') coming += size;
    if (r.status === 'invited') awaiting += size;
  });
  return { invited: invited, coming: coming, awaiting: awaiting };
}

function daysUntil(dateStr, nowMs) {
  var when = Date.parse(dateStr);
  if (!isFinite(when)) return null;
  return Math.ceil((when - nowMs) / (24 * 60 * 60 * 1000));
}

function eventLine(records, spentCents, eventDate, nowMs) {
  var heads = headcounts(records);
  var days = daysUntil(eventDate, nowMs);
  return (
    (days === null ? '' : days >= 0 ? days + ' day(s) to go. ' : 'The day has passed. ') +
    heads.coming +
    ' coming, ' +
    heads.awaiting +
    ' awaiting reply (' +
    heads.invited +
    ' invited). Spent ' +
    fmtCents(spentCents) +
    '.'
  );
}
// ── event-rules-end ──

const guests = rosterStore(gezel.fs, 'guests.json', {
  stages: ['invited', 'yes', 'no'],
  idPrefix: 'guest',
});
const budget = ledgerStore(gezel.fs, 'budget.json');

async function readEventDate(): Promise<string> {
  try {
    const parsed = JSON.parse(await gezel.fs.read('guests.json')) as { eventDate?: string };
    return typeof parsed.eventDate === 'string' ? parsed.eventDate : '';
  } catch {
    return '';
  }
}

async function resolveGuest(): Promise<string> {
  if (input.id) return input.id;
  if (input.name) {
    const wanted = input.name.toLowerCase();
    const matches = (await guests.list()).filter(
      (r) => String(r.fields.name ?? '').toLowerCase() === wanted,
    );
    if (matches.length === 1) return matches[0]!.id;
  }
  throw new Error("Pass 'id' (e.g. 'guest-4') or an exact guest 'name'.");
}

if (input.action === 'add_guest') {
  if (!input.name) throw new Error("add_guest needs 'name'.");
  await guests.add({
    status: 'invited',
    fields: {
      name: input.name,
      ...(typeof input.party === 'number' && input.party >= 1 ? { party: Math.floor(input.party) } : {}),
      ...(input.note ? { note: input.note } : {}),
    },
  });
} else if (input.action === 'guest_status') {
  if (!input.status || !['invited', 'yes', 'no'].includes(input.status)) {
    throw new Error("guest_status needs status 'invited', 'yes', or 'no'.");
  }
  await guests.transition(await resolveGuest(), input.status, input.note ? { note: input.note } : {});
} else if (input.action === 'record_spend') {
  const cents = toCents(input.amount);
  if (cents === null || !input.category) {
    throw new Error("record_spend needs a positive 'amount' and a 'category' (e.g. 'venue').");
  }
  await budget.add({
    amountCents: cents,
    kind: 'out',
    category: input.category.toLowerCase(),
    ...(input.note ? { note: input.note } : {}),
  });
} else if (input.action !== 'status' && input.action !== 'guest_list') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, add_guest, guest_status, record_spend, or guest_list.`,
  );
}

const records = await guests.list();
const totals = await budget.totals();
const heads = headcounts(records);
const eventDate = await readEventDate();
const listing =
  input.action === 'guest_list'
    ? records
        .map(
          (r) =>
            `${r.id} [${r.status}] ${String(r.fields.name ?? '?')}${partyOf(r) > 1 ? ` (party of ${partyOf(r)})` : ''}`,
        )
        .join('\n') || 'The guest list is empty.'
    : '';

gezel.output({
  invited: heads.invited,
  coming: heads.coming,
  spentCents: totals.outCents,
  summary: listing || eventLine(records, totals.outCents, eventDate, Date.now()),
});

scripts.training-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'training-store',
  description:
    "Read and update the training log (training.json). Call action:'status' for streak + this week vs the target; 'log_workout' the moment a session is reported (activity + minutes); 'set_target' to change the weekly session target; 'history' for the recent sessions.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'log_workout', 'set_target', or 'history'.",
      required: true,
    },
    activity: { type: 'string', description: "What they did, e.g. 'run', 'gym', 'long walk'." },
    minutes: { type: 'number', description: 'How long the session ran, in minutes.' },
    note: { type: 'string', description: 'Anything worth remembering about the session.' },
    weeklyTarget: { type: 'number', description: 'Sessions per week to aim for (set_target).' },
  },
  outputs: {
    streakDays: { type: 'number', description: 'Consecutive days with a session, ending at the latest.' },
    thisWeek: { type: 'number', description: 'Sessions logged this week (Monday UTC start).' },
    weeklyTarget: { type: 'number', description: 'The current weekly session target.' },
    summary: { type: 'string', description: 'The training picture.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── fitness-rules-start ──
// Pure derivations over logStore-shaped workout events: kind 'workout',
// data {activity, minutes}. Weeks start Monday 00:00 UTC; nowIso is a
// parameter so the rules stay clock-independent and testable.

function weekStartMs(nowIso) {
  var day = new Date(nowIso.slice(0, 10) + 'T00:00:00Z');
  var sinceMonday = (day.getUTCDay() + 6) % 7;
  return day.getTime() - sinceMonday * 86400000;
}

function thisWeekCount(events, nowIso) {
  var start = weekStartMs(nowIso);
  return events.filter(function (e) {
    return Date.parse(e.at) >= start;
  }).length;
}

function trainingLine(stats, weekCount, weeklyTarget) {
  var target = weeklyTarget > 0 ? weeklyTarget : 0;
  var weekPart =
    'This week: ' +
    weekCount +
    (target > 0 ? ' of ' + target + ' session(s)' : ' session(s)') +
    (target > 0 && weekCount >= target ? ' — target met.' : '.');
  var streakPart =
    stats.total === 0
      ? 'No sessions logged yet.'
      : 'Streak: ' + stats.streakDays + ' day(s); ' + stats.total + ' session(s) all time.';
  return weekPart + ' ' + streakPart;
}
// ── fitness-rules-end ──

const training = logStore(gezel.fs, 'training.json');

async function readWeeklyTarget(): Promise<number> {
  try {
    const parsed = JSON.parse(await gezel.fs.read('training.json')) as { weeklyTarget?: unknown };
    const target = Number(parsed.weeklyTarget);
    return Number.isFinite(target) && target > 0 ? Math.round(target) : 0;
  } catch {
    return 0;
  }
}

if (input.action === 'log_workout') {
  if (!input.activity) throw new Error("log_workout needs 'activity' (what they did).");
  await training.append({
    kind: 'workout',
    ...(input.note ? { note: input.note } : {}),
    data: {
      activity: input.activity,
      ...(typeof input.minutes === 'number' && input.minutes > 0
        ? { minutes: Math.round(input.minutes) }
        : {}),
    },
  });
} else if (input.action === 'set_target') {
  const target = Number(input.weeklyTarget);
  if (!Number.isFinite(target) || target <= 0) {
    throw new Error("set_target needs a positive 'weeklyTarget' (sessions per week).");
  }
  // logStore has no field API; the passenger key flips via a targeted
  // read-modify-write that preserves the rest of the file.
  const raw = JSON.parse(await gezel.fs.read('training.json')) as Record<string, unknown>;
  raw.weeklyTarget = Math.round(target);
  await gezel.fs.write('training.json', `${JSON.stringify(raw, null, 2)}\n`);
} else if (input.action !== 'status' && input.action !== 'history') {
  throw new Error(`Unknown action '${input.action}'. Use status, log_workout, set_target, or history.`);
}

const events = await training.list();
const stats = await training.stats();
const weeklyTarget = await readWeeklyTarget();
const nowIso = new Date().toISOString();
const weekCount = thisWeekCount(events, nowIso);
const listing =
  input.action === 'history'
    ? events
        .slice(-12)
        .map(
          (e) =>
            `${e.at.slice(0, 10)} ${String(e.data?.activity ?? 'session')}${typeof e.data?.minutes === 'number' ? ` (${e.data.minutes} min)` : ''}${e.note ? ` — ${e.note}` : ''}`,
        )
        .join('\n') || 'No sessions yet.'
    : '';

gezel.output({
  streakDays: stats.streakDays,
  thisWeek: weekCount,
  weeklyTarget,
  summary: listing || trainingLine(stats, weekCount, weeklyTarget),
});

scripts.deck-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'deck-store',
  description:
    "Read and update the flashcard deck (deck.json). Call action:'add_cards' with a cards array ([{front, back}, ...]) to add practice cards; action:'state' to see due counts and box distribution; action:'list_deck' to read every card. The review page drives 'record_review' and 'finish_session' itself.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'state', 'list_deck', 'add_cards', 'record_review', or 'finish_session'.",
      required: true,
    },
    cards: {
      type: 'json',
      description: 'For add_cards: an array of {front, back} objects.',
    },
    cardId: { type: 'string', description: "For record_review: the card id, e.g. 'card-3'." },
    verdict: { type: 'string', description: "For record_review: 'got-it' or 'missed'." },
    reviewed: { type: 'number', description: 'For finish_session: how many cards were reviewed.' },
    missedIds: { type: 'json', description: 'For finish_session: array of card ids that were missed.' },
  },
  outputs: {
    total: { type: 'number', description: 'Cards in the deck.' },
    due: { type: 'number', description: 'Cards due for review now.' },
    summary: { type: 'string', description: 'Human-readable deck or session summary.' },
    missedList: { type: 'string', description: 'Fronts of the cards missed this session (finish_session).' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── leitner-rules-start ──
// Pure Leitner-box scheduling (3 boxes). Box 1 reviews daily, box 2 every
// 3 days, box 3 weekly. A got-it promotes (capped at 3); a miss goes back
// to box 1. Never-reviewed cards are always due. Kept self-contained
// between these sentinels so unit tests execute the shipped bytes.

var BOX_INTERVAL_DAYS = { 1: 1, 2: 3, 3: 7 };
var DAY_MS = 24 * 60 * 60 * 1000;

function isDue(card, nowMs) {
  if (!card.lastReviewedAt) return true;
  var interval = BOX_INTERVAL_DAYS[card.box] || 1;
  return nowMs - Date.parse(card.lastReviewedAt) >= interval * DAY_MS;
}

function computeDueIds(cards, nowMs) {
  return cards
    .filter(function (c) {
      return isDue(c, nowMs);
    })
    .sort(function (a, b) {
      if (a.box !== b.box) return a.box - b.box;
      return a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : 0;
    })
    .map(function (c) {
      return c.id;
    });
}

function applyReview(card, verdict, nowIso) {
  if (verdict === 'got-it') card.box = Math.min(3, card.box + 1);
  else card.box = 1;
  card.lastReviewedAt = nowIso;
  card.stats = card.stats || { gotIt: 0, missed: 0 };
  if (verdict === 'got-it') card.stats.gotIt += 1;
  else card.stats.missed += 1;
  return card;
}

function nextCardId(cards) {
  var max = 0;
  for (var i = 0; i < cards.length; i += 1) {
    var m = /^card-(\d+)$/.exec(cards[i].id);
    if (m) max = Math.max(max, Number(m[1]));
  }
  return 'card-' + (max + 1);
}
// ── leitner-rules-end ──

const DECK_FILE = 'deck.json';

interface Card {
  id: string;
  front: string;
  back: string;
  box: number;
  lastReviewedAt: string | null;
  createdAt: string;
  stats: { gotIt: number; missed: number };
}

interface Deck {
  version: number;
  subject: string;
  cards: Card[];
  dueCardIds: string[];
  updatedAt: string;
}

async function load(): Promise<Deck> {
  let raw: string;
  try {
    raw = await gezel.fs.read(DECK_FILE);
  } catch {
    return { version: 1, subject: 'your subject', cards: [], dueCardIds: [], updatedAt: new Date().toISOString() };
  }
  const parsed = JSON.parse(raw) as Partial<Deck>;
  return {
    version: 1,
    subject: typeof parsed.subject === 'string' ? parsed.subject : 'your subject',
    cards: Array.isArray(parsed.cards) ? (parsed.cards as Card[]) : [],
    dueCardIds: [],
    updatedAt: new Date().toISOString(),
  };
}

async function persist(deck: Deck): Promise<Deck> {
  deck.dueCardIds = computeDueIds(deck.cards, Date.now());
  deck.updatedAt = new Date().toISOString();
  await gezel.fs.write(DECK_FILE, `${JSON.stringify(deck, null, 2)}\n`);
  return deck;
}

const deck = await load();
deck.dueCardIds = computeDueIds(deck.cards, Date.now());
let summary = '';
let missedList = '';

if (input.action === 'add_cards') {
  const raw = Array.isArray(input.cards) ? input.cards : [];
  const added: string[] = [];
  for (const entry of raw) {
    const front = typeof (entry as { front?: unknown }).front === 'string' ? (entry as { front: string }).front.trim() : '';
    const back = typeof (entry as { back?: unknown }).back === 'string' ? (entry as { back: string }).back.trim() : '';
    if (!front || !back) continue;
    const card: Card = {
      id: nextCardId(deck.cards),
      front: front.slice(0, 300),
      back: back.slice(0, 500),
      box: 1,
      lastReviewedAt: null,
      createdAt: new Date().toISOString(),
      stats: { gotIt: 0, missed: 0 },
    };
    deck.cards.push(card);
    added.push(card.id);
  }
  if (added.length === 0) {
    throw new Error("add_cards needs a non-empty 'cards' array of {front, back} objects.");
  }
  await persist(deck);
  summary = `Added ${added.length} card(s). ${deck.cards.length} in the deck, ${deck.dueCardIds.length} due now.`;
} else if (input.action === 'record_review') {
  if (!input.cardId || (input.verdict !== 'got-it' && input.verdict !== 'missed')) {
    throw new Error("record_review needs 'cardId' and verdict 'got-it' or 'missed'.");
  }
  const card = deck.cards.find((c) => c.id === input.cardId);
  if (!card) throw new Error(`No card '${input.cardId}' in the deck.`);
  applyReview(card, input.verdict, new Date().toISOString());
  await persist(deck);
  summary = `${card.id} marked ${input.verdict} (now box ${card.box}). ${deck.dueCardIds.length} still due.`;
} else if (input.action === 'finish_session') {
  const reviewed = typeof input.reviewed === 'number' ? input.reviewed : 0;
  const missedIds = Array.isArray(input.missedIds) ? input.missedIds.map(String) : [];
  const missedFronts = missedIds
    .map((id) => deck.cards.find((c) => c.id === id)?.front)
    .filter((f): f is string => typeof f === 'string');
  missedList = missedFronts.length ? missedFronts.join(' | ') : '(none)';
  summary = `Reviewed ${reviewed} card(s): ${reviewed - missedIds.length} got it, ${missedIds.length} missed. ${deck.dueCardIds.length} due next.`;
} else if (input.action === 'list_deck') {
  summary = deck.cards.length
    ? deck.cards
        .map((c) => `${c.id} [box ${c.box}] ${c.front} -> ${c.back}`)
        .join('\n')
    : 'The deck is empty — add cards with add_cards.';
} else if (input.action === 'state') {
  const boxes = { 1: 0, 2: 0, 3: 0 } as Record<number, number>;
  for (const c of deck.cards) boxes[c.box] = (boxes[c.box] ?? 0) + 1;
  summary = deck.cards.length
    ? `${deck.cards.length} card(s) on "${deck.subject}": ${deck.dueCardIds.length} due now. Boxes: ${boxes[1]} daily, ${boxes[2]} every-3-days, ${boxes[3]} weekly.`
    : `The deck for "${deck.subject}" is empty — offer to write the first cards.`;
} else {
  throw new Error(
    `Unknown action '${input.action}'. Use state, list_deck, add_cards, record_review, or finish_session.`,
  );
}

gezel.output({
  total: deck.cards.length,
  due: deck.dueCardIds.length,
  summary,
  missedList,
});

reaction.prompt:
The user finished a flashcard review session. {{output.summary}}
Missed cards: {{output.missedList}}
Reply with ONE short encouraging line — specific beats generic. If any cards were missed, offer to add fresh practice cards that come at those same ideas from a new angle (add them with your deck capabilities if the user agrees).

scripts.office-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'office-store',
  description:
    "Read and update the invoice book (invoices.json). Call action:'status' for outstanding/overdue/paid-this-month; 'record_invoice' when work is billed (amount in ordinary units, e.g. 1200.00); 'invoice_sent' / 'invoice_paid' as reality moves; 'list_invoices' to read the book.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'record_invoice', 'invoice_sent', 'invoice_paid', or 'list_invoices'.",
      required: true,
    },
    client: { type: 'string', description: 'Client name.' },
    amount: { type: 'number', description: 'Invoice amount in ordinary units, e.g. 1200.00.' },
    due: { type: 'string', description: 'Due date (ISO), e.g. 2026-08-15.' },
    note: { type: 'string', description: 'Short note (what the invoice covers).' },
    id: { type: 'string', description: "Invoice id, e.g. 'inv-3'." },
  },
  outputs: {
    invoices: { type: 'number', description: 'Invoices in the book.' },
    outstandingCents: { type: 'number', description: 'Total sent-but-unpaid, in cents.' },
    overdue: { type: 'number', description: 'Count of overdue invoices.' },
    summary: { type: 'string', description: 'Human-readable office summary.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── office-rules-start ──
// Pure derivations over rosterStore-shaped invoice records: statuses are
// draft -> sent -> paid; fields carry {client, amountCents, dueAt, note}.

function toCents(amount) {
  if (typeof amount !== 'number' || !isFinite(amount) || amount <= 0) return null;
  return Math.round(amount * 100);
}

function fmtCents(cents) {
  var sign = cents < 0 ? '-' : '';
  var abs = Math.abs(cents);
  return sign + Math.floor(abs / 100) + '.' + String(abs % 100).padStart(2, '0');
}

function officeShape(records, nowMs) {
  var outstanding = 0;
  var overdue = [];
  var paidMonth = 0;
  var month = new Date(nowMs).toISOString().slice(0, 7);
  records.forEach(function (r) {
    var cents = typeof r.fields.amountCents === 'number' ? r.fields.amountCents : 0;
    if (r.status === 'sent') {
      outstanding += cents;
      var due = typeof r.fields.dueAt === 'string' ? Date.parse(r.fields.dueAt) : NaN;
      if (isFinite(due) && due < nowMs) overdue.push(r);
    }
    if (r.status === 'paid' && r.updatedAt.slice(0, 7) === month) paidMonth += cents;
  });
  return { outstanding: outstanding, overdue: overdue, paidMonth: paidMonth, month: month };
}

function officeLine(records, nowMs) {
  var shape = officeShape(records, nowMs);
  var chase = shape.overdue
    .map(function (r) {
      return r.fields.client + ' (' + r.id + ', ' + fmtCents(r.fields.amountCents || 0) + ')';
    })
    .join(', ');
  return (
    'Outstanding ' +
    fmtCents(shape.outstanding) +
    ' across ' +
    records.filter(function (r) {
      return r.status === 'sent';
    }).length +
    ' sent invoice(s); ' +
    shape.overdue.length +
    ' overdue' +
    (chase ? ' (' + chase + ')' : '') +
    '. Paid this month: ' +
    fmtCents(shape.paidMonth) +
    '.'
  );
}
// ── office-rules-end ──

const invoices = rosterStore(gezel.fs, 'invoices.json', {
  stages: ['draft', 'sent', 'paid'],
  idPrefix: 'inv',
});

if (input.action === 'record_invoice') {
  const cents = toCents(input.amount);
  if (!input.client || cents === null) {
    throw new Error("record_invoice needs 'client' and a positive 'amount' (ordinary units).");
  }
  await invoices.add({
    fields: {
      client: input.client,
      amountCents: cents,
      ...(input.due ? { dueAt: input.due } : {}),
      ...(input.note ? { note: input.note } : {}),
    },
  });
} else if (input.action === 'invoice_sent' || input.action === 'invoice_paid') {
  if (!input.id) throw new Error("Pass the invoice 'id', e.g. 'inv-3'.");
  await invoices.transition(input.id, input.action === 'invoice_sent' ? 'sent' : 'paid');
} else if (input.action !== 'status' && input.action !== 'list_invoices') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, record_invoice, invoice_sent, invoice_paid, or list_invoices.`,
  );
}

const records = await invoices.list();
const shape = officeShape(records, Date.now());
const listing =
  input.action === 'list_invoices'
    ? records
        .map(
          (r) =>
            `${r.id} [${r.status}] ${String(r.fields.client ?? '?')} ${fmtCents(Number(r.fields.amountCents ?? 0))}${r.fields.dueAt ? ` due ${String(r.fields.dueAt).slice(0, 10)}` : ''}`,
        )
        .join('\n') || 'The invoice book is empty.'
    : '';

gezel.output({
  invoices: records.length,
  outstandingCents: shape.outstanding,
  overdue: shape.overdue.length,
  summary: listing || officeLine(records, Date.now()),
});

scripts.drive-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { ledgerStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'drive-store',
  description:
    "Read and update the fundraising drive (donations.json). Call action:'status' for the thermometer + unthanked list; 'record_donation' the moment a gift lands (ordinary units, donor name); 'mark_thanked' once the thank-you goes out.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'record_donation', 'mark_thanked', or 'donor_list'.",
      required: true,
    },
    donor: { type: 'string', description: "Donor name ('anonymous' is fine)." },
    amount: { type: 'number', description: 'Gift amount in ordinary units.' },
    note: { type: 'string', description: 'Anything worth remembering about the gift.' },
    id: { type: 'string', description: "Donation id, e.g. 'ledger-4'." },
  },
  outputs: {
    raisedCents: { type: 'number', description: 'Total raised, in cents.' },
    donors: { type: 'number', description: 'Number of gifts.' },
    unthanked: { type: 'number', description: 'Gifts still awaiting a thank-you.' },
    summary: { type: 'string', description: 'The drive picture.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── drive-rules-start ──
// Pure derivations over ledgerStore-shaped donation entries: entries are
// kind 'in', category 'donation', data {donor, thanked}.

function toCents(amount) {
  if (typeof amount !== 'number' || !isFinite(amount) || amount <= 0) return null;
  return Math.round(amount * 100);
}

function fmtCents(cents) {
  var abs = Math.abs(cents);
  return (cents < 0 ? '-' : '') + Math.floor(abs / 100) + '.' + String(abs % 100).padStart(2, '0');
}

function driveShape(entries) {
  var raised = 0;
  var unthanked = [];
  entries.forEach(function (e) {
    raised += e.amountCents;
    if (!e.data || e.data.thanked !== true) unthanked.push(e);
  });
  return { raised: raised, unthanked: unthanked };
}

function driveLine(entries, goalCents) {
  var shape = driveShape(entries);
  var pct = goalCents > 0 ? Math.min(100, Math.round((shape.raised / goalCents) * 100)) : null;
  return (
    'Raised ' +
    fmtCents(shape.raised) +
    (goalCents > 0 ? ' of ' + fmtCents(goalCents) + ' (' + pct + ' percent)' : '') +
    ' across ' +
    entries.length +
    ' gift(s). ' +
    (shape.unthanked.length === 0
      ? 'Everyone thanked.'
      : shape.unthanked.length + ' thank-you(s) still owed.')
  );
}
// ── drive-rules-end ──

const donations = ledgerStore(gezel.fs, 'donations.json');

async function readGoalCents(): Promise<number> {
  try {
    const parsed = JSON.parse(await gezel.fs.read('donations.json')) as { goalCents?: unknown };
    const goal = Number(parsed.goalCents);
    return Number.isFinite(goal) && goal > 0 ? Math.round(goal) : 0;
  } catch {
    return 0;
  }
}

if (input.action === 'record_donation') {
  const cents = toCents(input.amount);
  if (cents === null) throw new Error("record_donation needs a positive 'amount' (ordinary units).");
  await donations.add({
    amountCents: cents,
    kind: 'in',
    category: 'donation',
    ...(input.note ? { note: input.note } : {}),
    data: { donor: input.donor || 'anonymous', thanked: false },
  });
} else if (input.action === 'mark_thanked') {
  if (!input.id && !input.donor) throw new Error("Pass 'id' (e.g. 'ledger-4') or a unique 'donor'.");
  // ledgerStore is append-only by design; thanked flips via a targeted
  // read-modify-write on the entry's data (the one mutation this drive needs).
  const raw = JSON.parse(await gezel.fs.read('donations.json')) as {
    entries: Array<{ id: string; data?: { donor?: string; thanked?: boolean } }>;
  };
  const matches = raw.entries.filter((e) =>
    input.id
      ? e.id === input.id
      : String(e.data?.donor ?? '').toLowerCase() === String(input.donor).toLowerCase() &&
        e.data?.thanked !== true,
  );
  if (matches.length === 0) throw new Error('No matching unthanked donation found.');
  if (matches.length > 1 && !input.id) {
    throw new Error(
      `Multiple unthanked gifts from '${input.donor}': ${matches.map((m) => m.id).join(', ')}. Pass id.`,
    );
  }
  matches[0]!.data = { ...(matches[0]!.data ?? {}), thanked: true };
  await gezel.fs.write('donations.json', `${JSON.stringify(raw, null, 2)}\n`);
} else if (input.action !== 'status' && input.action !== 'donor_list') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, record_donation, mark_thanked, or donor_list.`,
  );
}

const entries = await donations.list();
const goalCents = await readGoalCents();
const shape = driveShape(entries);
const listing =
  input.action === 'donor_list'
    ? entries
        .map(
          (e) =>
            `${e.id} ${fmtCents(e.amountCents)} from ${String(e.data?.donor ?? 'anonymous')}${e.data?.thanked === true ? '' : ' (thank-you owed)'}`,
        )
        .join('\n') || 'No gifts yet.'
    : '';

gezel.output({
  raisedCents: shape.raised,
  donors: entries.length,
  unthanked: shape.unthanked.length,
  summary: listing || driveLine(entries, goalCents),
});

scripts.game-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'game-store',
  description:
    "Read and update the Go game (game.json). Call action:'board' to see the position and every legal move; action:'ai_move' to play a coordinate such as D4 or 'pass' (optional moveThought); action:'state' for a light summary; action:'new_game' to reset with boardSize 9, 13, or 19 and optional komi. The engine enforces captures, suicide, simple ko, passing, and area scoring.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'state', 'board', 'user_move', 'ai_move', or 'new_game'.",
      required: true,
    },
    move: {
      type: 'string',
      description: "A board coordinate such as 'D4', or 'pass'.",
    },
    boardSize: {
      type: 'number',
      description: 'For new_game: 9, 13, or 19. Defaults to 9.',
    },
    komi: {
      type: 'number',
      description: 'For new_game: points added to white. Defaults to 6.5.',
    },
    moveThought: {
      type: 'string',
      description: 'A short line of table talk to show on the board (max 140 chars).',
    },
  },
  outputs: {
    board: { type: 'string', description: 'ASCII board with coordinates.' },
    turn: { type: 'string', description: "Whose move: 'user' (black) or 'ai' (white)." },
    status: {
      type: 'string',
      description: 'playing, user_won, ai_won, or draw.',
    },
    lastMove: { type: 'string', description: "The move just played, e.g. 'D4' or 'pass'." },
    legalMoves: { type: 'string', description: 'Legal placements plus pass.' },
    score: { type: 'string', description: 'Area score when the game has ended.' },
    summary: { type: 'string', description: 'Human-readable game summary.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── go-rules-start ──
// Pure, annotation-free Go engine. Supports 9x9, 13x13, and 19x19.
// Squares are row-major, y0 at the top. X = black/user; O = white/AI.
// Coordinates follow Go convention and skip the letter I.

var GO_FILES = 'ABCDEFGHJKLMNOPQRST';

function buildInitial(size) {
  return '.'.repeat(size * size);
}

function inBounds(x, y, size) {
  return x >= 0 && x < size && y >= 0 && y < size;
}

function pointName(x, y, size) {
  return GO_FILES[x] + String(size - y);
}

function parsePoint(name, size) {
  if (typeof name !== 'string') return null;
  var text = name.trim().toUpperCase();
  var match = /^([A-HJ-T])(\d{1,2})$/.exec(text);
  if (!match) return null;
  var x = GO_FILES.indexOf(match[1]);
  var rank = Number(match[2]);
  if (x < 0 || x >= size || rank < 1 || rank > size) return null;
  return { x: x, y: size - rank, index: (size - rank) * size + x };
}

function neighbors(index, size) {
  var x = index % size;
  var y = Math.floor(index / size);
  var out = [];
  if (x > 0) out.push(index - 1);
  if (x + 1 < size) out.push(index + 1);
  if (y > 0) out.push(index - size);
  if (y + 1 < size) out.push(index + size);
  return out;
}

function groupAt(squares, index, size) {
  var color = squares[index];
  var stones = [];
  var liberties = {};
  var seen = {};
  var queue = [index];
  seen[index] = true;
  while (queue.length) {
    var current = queue.pop();
    stones.push(current);
    for (var next of neighbors(current, size)) {
      if (squares[next] === '.') liberties[next] = true;
      else if (squares[next] === color && !seen[next]) {
        seen[next] = true;
        queue.push(next);
      }
    }
  }
  return { stones: stones, liberties: Object.keys(liberties).map(Number) };
}

function replaceAt(squares, index, ch) {
  return squares.slice(0, index) + ch + squares.slice(index + 1);
}

function applyPlacement(squares, size, side, name, previousPosition) {
  var point = parsePoint(name, size);
  if (!point) return { error: 'bad-coordinate' };
  if (squares[point.index] !== '.') return { error: 'occupied' };
  var stone = side === 'user' ? 'X' : 'O';
  var enemy = side === 'user' ? 'O' : 'X';
  var next = replaceAt(squares, point.index, stone);
  var captures = [];
  var checked = {};
  for (var adjacent of neighbors(point.index, size)) {
    if (next[adjacent] !== enemy || checked[adjacent]) continue;
    var enemyGroup = groupAt(next, adjacent, size);
    for (var member of enemyGroup.stones) checked[member] = true;
    if (enemyGroup.liberties.length === 0) {
      for (var captured of enemyGroup.stones) {
        next = replaceAt(next, captured, '.');
        captures.push(pointName(captured % size, Math.floor(captured / size), size));
      }
    }
  }
  if (groupAt(next, point.index, size).liberties.length === 0) return { error: 'suicide' };
  if (previousPosition && next === previousPosition) return { error: 'ko' };
  return { squares: next, captures: captures };
}

function legalMovesFor(squares, size, side, previousPosition) {
  var moves = [];
  for (var y = 0; y < size; y += 1) {
    for (var x = 0; x < size; x += 1) {
      if (squares[y * size + x] !== '.') continue;
      var name = pointName(x, y, size);
      var result = applyPlacement(squares, size, side, name, previousPosition);
      if (!result.error) moves.push(name);
    }
  }
  moves.push('pass');
  return moves;
}

function scoreArea(squares, size, komi) {
  var blackStones = 0;
  var whiteStones = 0;
  var blackTerritory = 0;
  var whiteTerritory = 0;
  var seen = {};
  for (var i = 0; i < squares.length; i += 1) {
    if (squares[i] === 'X') {
      blackStones += 1;
      continue;
    }
    if (squares[i] === 'O') {
      whiteStones += 1;
      continue;
    }
    if (seen[i]) continue;
    var region = [];
    var borders = {};
    var queue = [i];
    seen[i] = true;
    while (queue.length) {
      var current = queue.pop();
      region.push(current);
      for (var next of neighbors(current, size)) {
        if (squares[next] === '.' && !seen[next]) {
          seen[next] = true;
          queue.push(next);
        } else if (squares[next] === 'X' || squares[next] === 'O') {
          borders[squares[next]] = true;
        }
      }
    }
    if (borders.X && !borders.O) blackTerritory += region.length;
    if (borders.O && !borders.X) whiteTerritory += region.length;
  }
  var black = blackStones + blackTerritory;
  var white = whiteStones + whiteTerritory + komi;
  return {
    black: black,
    white: white,
    blackStones: blackStones,
    whiteStones: whiteStones,
    blackTerritory: blackTerritory,
    whiteTerritory: whiteTerritory,
    winner: black === white ? 'draw' : black > white ? 'user' : 'ai',
    margin: Math.abs(black - white),
  };
}

function statusAfter(squares, size, komi, consecutivePasses) {
  if (consecutivePasses < 2) return 'playing';
  var score = scoreArea(squares, size, komi);
  return score.winner === 'draw' ? 'draw' : score.winner === 'user' ? 'user_won' : 'ai_won';
}

function renderAscii(squares, size) {
  var labels = [];
  for (var x = 0; x < size; x += 1) labels.push(GO_FILES[x]);
  var pad = size >= 10 ? '   ' : '  ';
  var lines = [pad + labels.join(' ')];
  for (var y = 0; y < size; y += 1) {
    var rank = String(size - y).padStart(size >= 10 ? 2 : 1, ' ');
    var row = [];
    for (var x = 0; x < size; x += 1) row.push(squares[y * size + x]);
    lines.push(rank + ' ' + row.join(' ') + ' ' + rank);
  }
  lines.push(pad + labels.join(' '));
  lines.push('X = black (user). O = white (you).');
  return lines.join('\n');
}
// ── go-rules-end ──

const STATE_FILE = 'game.json';
const SIDE_NAMES = { user: 'black', ai: 'white' };

interface GameState {
  version: number;
  boardSize: number;
  squares: string;
  turn: 'user' | 'ai';
  status: 'playing' | 'user_won' | 'ai_won' | 'draw';
  komi: number;
  consecutivePasses: number;
  previousPosition: string | null;
  legalMoves: string[];
  captures: { user: number; ai: number };
  score: ReturnType<typeof scoreArea> | null;
  moveLog: Array<{
    by: 'user' | 'ai';
    move: string;
    captures: string[];
    at: string;
    moveThought?: string;
  }>;
  lastMove: { by: 'user' | 'ai'; move: string; captures: string[] } | null;
  lastMoveThought: string;
  updatedAt: string;
}

function validSize(value: unknown): number {
  const size = Number(value);
  return size === 13 || size === 19 ? size : 9;
}

function validKomi(value: unknown): number {
  const komi = Number(value);
  return Number.isFinite(komi) && komi >= 0 && komi <= 20 ? komi : 6.5;
}

function freshState(boardSize = 9, komi = 6.5): GameState {
  const size = validSize(boardSize);
  const nextKomi = validKomi(komi);
  const squares = buildInitial(size);
  return {
    version: 1,
    boardSize: size,
    squares,
    turn: 'user',
    status: 'playing',
    komi: nextKomi,
    consecutivePasses: 0,
    previousPosition: null,
    legalMoves: legalMovesFor(squares, size, 'user', null),
    captures: { user: 0, ai: 0 },
    score: null,
    moveLog: [],
    lastMove: null,
    lastMoveThought: '',
    updatedAt: new Date().toISOString(),
  };
}

async function load(): Promise<GameState> {
  let raw: string;
  try {
    raw = await gezel.fs.read(STATE_FILE);
  } catch {
    return freshState();
  }
  const parsed = JSON.parse(raw) as Partial<GameState>;
  const size = validSize(parsed.boardSize);
  if (typeof parsed.squares !== 'string' || parsed.squares.length !== size * size) {
    throw new Error(`${STATE_FILE} is corrupt; call action:'new_game' to reset.`);
  }
  return {
    ...freshState(size, parsed.komi),
    ...parsed,
    boardSize: size,
    komi: validKomi(parsed.komi),
  } as GameState;
}

async function persist(state: GameState): Promise<GameState> {
  state.legalMoves =
    state.status === 'playing'
      ? legalMovesFor(
          state.squares,
          state.boardSize,
          state.turn,
          state.previousPosition,
        )
      : [];
  state.updatedAt = new Date().toISOString();
  await gezel.fs.write(STATE_FILE, `${JSON.stringify(state, null, 2)}\n`);
  return state;
}

function renderLegal(state: GameState): string {
  if (state.status !== 'playing') return '(game over)';
  return state.legalMoves.join(', ');
}

function renderScore(state: GameState): string {
  if (!state.score) return '(not scored — play continues)';
  const result =
    state.score.winner === 'draw'
      ? 'draw'
      : `${SIDE_NAMES[state.score.winner]} wins by ${state.score.margin}`;
  return `Black ${state.score.black}; white ${state.score.white} (includes ${state.komi} komi): ${result}.`;
}

function summarize(state: GameState): string {
  if (state.status !== 'playing') return `Game over. ${renderScore(state)}`;
  return `Move ${state.moveLog.length + 1}: ${SIDE_NAMES[state.turn]} (${state.turn}) to move on ${state.boardSize}x${state.boardSize}. Captures — black ${state.captures.user}, white ${state.captures.ai}.`;
}

function applyTurn(
  state: GameState,
  by: 'user' | 'ai',
  moveThought?: string,
): GameState {
  if (state.status !== 'playing') {
    throw new Error(`The game is over (${state.status}). Call action:'new_game' to start another.`);
  }
  if (state.turn !== by) {
    throw new Error(by === 'ai' ? "It's not your turn yet." : 'The opponent is still to move.');
  }
  const move = input.move?.trim() || '';
  const normalized = move.toLowerCase() === 'pass' ? 'pass' : move.toUpperCase();
  if (!state.legalMoves.includes(normalized)) {
    throw new Error(
      `Illegal move '${move}'. Legal moves for ${SIDE_NAMES[by]}: ${renderLegal(state)}`,
    );
  }

  let captured: string[] = [];
  const before = state.squares;
  if (normalized === 'pass') {
    state.consecutivePasses += 1;
  } else {
    const applied = applyPlacement(
      state.squares,
      state.boardSize,
      by,
      normalized,
      state.previousPosition,
    );
    if (applied.error || !applied.squares) {
      throw new Error(`Illegal move '${move}' (${applied.error || 'unknown'}).`);
    }
    state.squares = applied.squares;
    captured = applied.captures || [];
    state.captures[by] += captured.length;
    state.consecutivePasses = 0;
  }
  state.previousPosition = before;
  state.turn = (by === 'user' ? 'ai' : 'user') as 'user' | 'ai';
  state.status = statusAfter(
    state.squares,
    state.boardSize,
    state.komi,
    state.consecutivePasses,
  ) as GameState['status'];
  if (state.status !== 'playing') {
    state.score = scoreArea(state.squares, state.boardSize, state.komi);
  }
  const entry = {
    by,
    move: normalized,
    captures: captured,
    at: new Date().toISOString(),
    ...(moveThought ? { moveThought } : {}),
  };
  state.moveLog.push(entry);
  state.lastMove = { by, move: normalized, captures: captured };
  if (by === 'ai' && moveThought) state.lastMoveThought = moveThought;
  return state;
}

let state = await load();
let lastMoveText = state.lastMove?.move ?? '(none)';

if (input.action === 'new_game') {
  state = await persist(freshState(input.boardSize, input.komi));
  lastMoveText = '(none)';
} else if (input.action === 'user_move' || input.action === 'ai_move') {
  const by = input.action === 'user_move' ? 'user' : 'ai';
  const moveThought = input.moveThought?.trim().slice(0, 140);
  state = await persist(applyTurn(state, by, moveThought));
  lastMoveText = state.lastMove?.move ?? '(none)';
} else if (input.action !== 'state' && input.action !== 'board') {
  throw new Error(`Unknown action '${input.action}'. Use state, board, user_move, ai_move, or new_game.`);
}

gezel.output({
  board:
    `${renderAscii(state.squares, state.boardSize)}\nTurn: ${SIDE_NAMES[state.turn]} (${state.turn}).\n` +
    `Komi: ${state.komi}. Consecutive passes: ${state.consecutivePasses}.\n` +
    `Legal moves: ${renderLegal(state)}`,
  turn: state.turn,
  status: state.status,
  lastMove: lastMoveText,
  legalMoves: renderLegal(state),
  score: renderScore(state),
  summary: summarize(state),
});

scripts.budget-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { ledgerStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'budget-store',
  description:
    "Read and update the household ledger (ledger.json). Call action:'status' for this month's shape (in/out/net, top categories); 'add_expense' or 'add_income' the moment money moves (amount in ordinary units, e.g. 12.50); 'month_summary' with month 'YYYY-MM' for any past month.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add_expense', 'add_income', or 'month_summary'.",
      required: true,
    },
    amount: { type: 'number', description: 'Amount in ordinary currency units, e.g. 12.50.' },
    category: { type: 'string', description: "Category, e.g. 'groceries', 'rent', 'salary'." },
    note: { type: 'string', description: 'Short note on the entry.' },
    month: { type: 'string', description: "Month for month_summary, e.g. '2026-06'." },
  },
  outputs: {
    entries: { type: 'number', description: 'Total ledger entries.' },
    summary: { type: 'string', description: 'Human-readable money summary.' },
    netCents: { type: 'number', description: 'Net for the summarized month, in cents.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── budget-rules-start ──
// Pure derivations shared with tests: cents conversion and the month
// summary line, kept engine-side so the dashboard, the tools, and the
// tests agree on one rendering.

function toCents(amount) {
  if (typeof amount !== 'number' || !isFinite(amount) || amount <= 0) return null;
  return Math.round(amount * 100);
}

function fmtCents(cents) {
  var sign = cents < 0 ? '-' : '';
  var abs = Math.abs(cents);
  return sign + Math.floor(abs / 100) + '.' + String(abs % 100).padStart(2, '0');
}

function topCategories(byCategory, kind, limit) {
  return Object.entries(byCategory)
    .map(function (pair) {
      return { category: pair[0], cents: kind === 'out' ? pair[1].outCents : pair[1].inCents };
    })
    .filter(function (row) {
      return row.cents > 0;
    })
    .sort(function (a, b) {
      return b.cents - a.cents;
    })
    .slice(0, limit);
}

function monthLine(month, totals) {
  var top = topCategories(totals.byCategory, 'out', 3)
    .map(function (row) {
      return row.category + ' ' + fmtCents(row.cents);
    })
    .join(', ');
  return (
    month +
    ': in ' +
    fmtCents(totals.inCents) +
    ', out ' +
    fmtCents(totals.outCents) +
    ', net ' +
    fmtCents(totals.netCents) +
    (top ? '. Biggest: ' + top + '.' : '. No spending recorded.')
  );
}
// ── budget-rules-end ──

const ledger = ledgerStore(gezel.fs, 'ledger.json');
const currentMonth = new Date().toISOString().slice(0, 7);

if (input.action === 'add_expense' || input.action === 'add_income') {
  const cents = toCents(input.amount);
  if (cents === null) throw new Error("Pass a positive 'amount' in ordinary units, e.g. 12.50.");
  if (!input.category) throw new Error("Pass a 'category', e.g. 'groceries' or 'salary'.");
  await ledger.add({
    amountCents: cents,
    kind: input.action === 'add_expense' ? 'out' : 'in',
    category: input.category.toLowerCase(),
    ...(input.note ? { note: input.note } : {}),
  });
} else if (input.action !== 'status' && input.action !== 'month_summary') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, add_expense, add_income, or month_summary.`,
  );
}

const month =
  input.action === 'month_summary' && input.month ? input.month : currentMonth;
const totals = await ledger.totals({ month });
const all = await ledger.list();

gezel.output({
  entries: all.length,
  summary: monthLine(month, totals),
  netCents: totals.netCents,
});

scripts.house-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'house-store',
  description:
    "Read and update the home's system cards (systems.json). Call action:'status' for what's due or flagged; 'record_system' when an appliance/system comes up (with care interval in days when known); 'log_maintenance' when care happens; 'flag_attention' for problems; 'house_list' to read every card.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'record_system', 'log_maintenance', 'flag_attention', or 'house_list'.",
      required: true,
    },
    name: { type: 'string', description: "System name, e.g. 'Furnace', 'Smoke alarms'." },
    kind: { type: 'string', description: 'What it is (appliance, safety, structure, utility).' },
    location: { type: 'string', description: 'Where it lives in the house.' },
    care: { type: 'string', description: "The care it needs, e.g. 'replace filter'." },
    intervalDays: { type: 'number', description: 'Care interval in days, when known.' },
    note: { type: 'string', description: 'Maintenance or attention note.' },
    id: { type: 'string', description: "System id, e.g. 'sys-2'." },
  },
  outputs: {
    systems: { type: 'number', description: 'System cards in the manual.' },
    due: { type: 'number', description: 'Systems with care due.' },
    flagged: { type: 'number', description: 'Systems flagged for attention.' },
    summary: { type: 'string', description: 'What the house needs.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── house-rules-start ──
// Pure derivations over rosterStore-shaped system cards: statuses are
// ok -> attention; "due" derives from lastDoneAt + intervalDays.

var DAY_MS = 24 * 60 * 60 * 1000;

function isDue(record, nowMs) {
  var f = record.fields || {};
  if (typeof f.intervalDays !== 'number' || f.intervalDays <= 0) return false;
  var last = typeof f.lastDoneAt === 'string' ? Date.parse(f.lastDoneAt) : Date.parse(record.createdAt);
  return isFinite(last) && nowMs - last >= f.intervalDays * DAY_MS;
}

function houseShape(records, nowMs) {
  var due = [];
  var flagged = [];
  records.forEach(function (r) {
    if (isDue(r, nowMs)) due.push(r);
    if (r.status === 'attention') flagged.push(r);
  });
  return { due: due, flagged: flagged };
}

function houseLine(records, nowMs) {
  var shape = houseShape(records, nowMs);
  var names = function (rows) {
    return rows
      .map(function (r) {
        return (r.fields && r.fields.name) || r.id;
      })
      .join(', ');
  };
  if (records.length === 0) return 'No systems recorded yet — start with the ones that need regular care.';
  var bits = [];
  if (shape.due.length) bits.push('care due: ' + names(shape.due));
  if (shape.flagged.length) bits.push('flagged: ' + names(shape.flagged));
  return records.length + ' system(s) on record. ' + (bits.length ? bits.join('; ') + '.' : 'Nothing due — the house is quiet.');
}
// ── house-rules-end ──

const house = rosterStore(gezel.fs, 'systems.json', {
  stages: ['ok', 'attention'],
  idPrefix: 'sys',
});

async function resolveSystem(): Promise<string> {
  if (input.id) return input.id;
  if (input.name) {
    const wanted = input.name.toLowerCase();
    const matches = (await house.list()).filter(
      (r) => String(r.fields.name ?? '').toLowerCase() === wanted,
    );
    if (matches.length === 1) return matches[0]!.id;
  }
  throw new Error("Pass 'id' (e.g. 'sys-2') or an exact system 'name'.");
}

if (input.action === 'record_system') {
  if (!input.name) throw new Error("record_system needs 'name'.");
  await house.add({
    status: 'ok',
    fields: {
      name: input.name,
      ...(input.kind ? { kind: input.kind } : {}),
      ...(input.location ? { location: input.location } : {}),
      ...(input.care ? { care: input.care } : {}),
      ...(typeof input.intervalDays === 'number' ? { intervalDays: input.intervalDays } : {}),
      lastDoneAt: new Date().toISOString(),
    },
  });
} else if (input.action === 'log_maintenance') {
  const id = await resolveSystem();
  await house.update(id, {
    fields: { lastDoneAt: new Date().toISOString() },
    ...(input.note ? { note: input.note } : {}),
  });
  await house.transition(id, 'ok');
} else if (input.action === 'flag_attention') {
  const id = await resolveSystem();
  await house.transition(id, 'attention', input.note ? { note: input.note } : {});
} else if (input.action !== 'status' && input.action !== 'house_list') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, record_system, log_maintenance, flag_attention, or house_list.`,
  );
}

const records = await house.list();
const shape = houseShape(records, Date.now());
const listing =
  input.action === 'house_list'
    ? records
        .map(
          (r) =>
            `${r.id} [${r.status}${isDue(r, Date.now()) ? ', due' : ''}] ${String(r.fields.name ?? '?')}${r.fields.location ? ` — ${String(r.fields.location)}` : ''}${r.fields.care ? ` (${String(r.fields.care)}${r.fields.intervalDays ? ` every ${String(r.fields.intervalDays)}d` : ''})` : ''}`,
        )
        .join('\n') || 'No systems recorded yet.'
    : '';

gezel.output({
  systems: records.length,
  due: shape.due.length,
  flagged: shape.flagged.length,
  summary: listing || houseLine(records, Date.now()),
});

scripts.posts-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'posts-store',
  description:
    "Read and update the post pipeline under posts/. Call action:'list' to see every post (optional status/platform filters); 'get' for one post's frontmatter, body, variants, and media; 'create' to commit the staged posts/_drafting/ folder as a real post; 'update' to patch frontmatter or move a post one pipeline stage (idea, draft, in-review, approved, scheduled, published, archived from anywhere); 'record_publication' to stamp a platform variant with its permalink after it goes live. Illegal stage jumps fail with the legal next stages — move one stage at a time.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'list', 'get', 'create', 'update', or 'record_publication'.",
      required: true,
    },
    id: { type: 'string', description: "Post id — its folder name under posts/, e.g. '2026-08-12-launch-teaser'." },
    status: {
      type: 'string',
      description: "Target status: idea, draft, in-review, approved, scheduled, published, or archived. For 'create', the initial status (defaults to approved).",
    },
    platform: { type: 'string', description: "Platform filter for 'list', or the published variant for 'record_publication' (e.g. 'bluesky')." },
    fields: {
      type: 'json',
      description: "For 'update': an object of frontmatter patches, e.g. {\"scheduledFor\": \"2026-08-15T09:00:00Z\", \"campaign\": \"autumn\"}. A null value clears the key.",
    },
    permalink: { type: 'string', description: 'Public URL of the live post, for record_publication.' },
    postId: { type: 'string', description: "The platform's own id for the live post, for record_publication." },
    corpusRef: { type: 'string', description: 'Connector corpus record reference for the live post, when one exists.' },
    publishedAt: { type: 'string', description: 'ISO timestamp the post went live (defaults to now).' },
    markPublished: {
      type: 'boolean',
      description: 'For record_publication: force the post to published even if other target platforms are not stamped yet.',
    },
  },
  outputs: {
    posts: { type: 'json', description: "For 'list': the post listing entries." },
    total: { type: 'number', description: "For 'list': how many posts exist before filtering." },
    post: { type: 'json', description: "For 'get': frontmatter plus body, variants map, and media names." },
    id: { type: 'string', description: 'The post id the action touched.' },
    status: { type: 'string', description: "The post's status after the action." },
    summary: { type: 'string', description: 'Human-readable result.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

const POSTS_DIR = 'posts';
const DRAFTING = 'posts/_drafting';
const INDEX_FILE = 'posts/index.json';
const ID_RE = /^[a-z0-9][a-z0-9-]{0,99}$/;
const PLATFORM_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;
const STAGES = ['idea', 'draft', 'in-review', 'approved', 'scheduled', 'published'] as const;
const STATUSES: string[] = [...STAGES, 'archived'];

// ── frontmatter ──
// Hand-rolled, deliberately simple: `---`-delimited `key: value` lines,
// arrays as [a, b]. Unknown keys and even unparseable lines are preserved
// in order so a round-trip never loses what a human or another tool wrote.

type FmEntry = { key: string; value: string | string[] } | { raw: string };
interface FmDoc {
  entries: FmEntry[];
  body: string;
}

function parseArrayish(value: string): string[] {
  return value
    .slice(1, -1)
    .split(',')
    .map((part) => part.trim().replace(/^["']|["']$/g, ''))
    .filter((part) => part.length > 0);
}

function parseFrontmatter(text: string): FmDoc {
  const lines = text.split(/\r?\n/);
  if (lines[0]?.trim() !== '---') return { entries: [], body: text };
  const entries: FmEntry[] = [];
  let at = 1;
  for (; at < lines.length; at += 1) {
    const line = lines[at]!;
    if (line.trim() === '---') {
      return { entries, body: lines.slice(at + 1).join('\n').replace(/^\n/, '') };
    }
    const sep = line.indexOf(':');
    if (sep <= 0) {
      if (line.trim().length > 0) entries.push({ raw: line });
      continue;
    }
    const key = line.slice(0, sep).trim();
    const value = line.slice(sep + 1).trim();
    if (!key) {
      entries.push({ raw: line });
      continue;
    }
    entries.push({
      key,
      value: value.startsWith('[') && value.endsWith(']') ? parseArrayish(value) : value,
    });
  }
  return { entries: [], body: text };
}

function serializeFrontmatter(doc: FmDoc): string {
  const lines = doc.entries.map((entry) => {
    if ('raw' in entry) return entry.raw;
    const value = Array.isArray(entry.value) ? `[${entry.value.join(', ')}]` : entry.value;
    return `${entry.key}: ${value}`;
  });
  return `---\n${lines.join('\n')}\n---\n\n${doc.body.replace(/^\n+/, '')}`;
}

function fmGet(doc: FmDoc, key: string): string | string[] | undefined {
  for (const entry of doc.entries) {
    if ('key' in entry && entry.key === key) return entry.value;
  }
  return undefined;
}

function fmGetString(doc: FmDoc, key: string): string {
  const value = fmGet(doc, key);
  if (Array.isArray(value)) return value.join(', ');
  return value ?? '';
}

function fmGetArray(doc: FmDoc, key: string): string[] {
  const value = fmGet(doc, key);
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.length > 0) return [value];
  return [];
}

function fmSet(doc: FmDoc, key: string, value: string | string[]): void {
  for (const entry of doc.entries) {
    if ('key' in entry && entry.key === key) {
      entry.value = value;
      return;
    }
  }
  doc.entries.push({ key, value });
}

function fmDelete(doc: FmDoc, key: string): void {
  doc.entries = doc.entries.filter((entry) => !('key' in entry && entry.key === key));
}

// ── pipeline rules ──

function legalNext(from: string): string[] {
  if (from === 'archived') return [];
  const at = STAGES.indexOf(from as (typeof STAGES)[number]);
  const forward = at >= 0 && at < STAGES.length - 1 ? [STAGES[at + 1]!] : [];
  return [...forward, 'archived'];
}

function assertTransition(id: string, from: string, to: string): void {
  if (to === from) return;
  if (!STATUSES.includes(to)) {
    throw new Error(`Unknown status '${to}'. Statuses: ${STATUSES.join(', ')}.`);
  }
  if (!legalNext(from).includes(to)) {
    const next = legalNext(from);
    throw new Error(
      `Cannot move '${id}' from ${from} to ${to} — posts move one stage at a time. ` +
        (next.length > 0 ? `Legal next: ${next.join(', ')}.` : `'${from}' is final; create a new post instead.`),
    );
  }
}

function requireId(): string {
  const id = (input.id ?? '').trim();
  if (!id) throw new Error("Pass 'id' — the post's folder name under posts/ (see action:'list').");
  if (!ID_RE.test(id)) {
    throw new Error(`Invalid post id '${id}'. Ids are lowercase [a-z0-9-], no slashes or dots.`);
  }
  return id;
}

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
}

// ── store ──

interface IndexEntry {
  id: string;
  title: string;
  status: string;
  platforms: string[];
  created: string;
  scheduledFor?: string;
  campaign?: string;
}

async function readPostDoc(id: string): Promise<FmDoc> {
  let raw: string;
  try {
    raw = await gezel.fs.read(`${POSTS_DIR}/${id}/post.md`);
  } catch {
    throw new Error(`No post '${id}' — posts/${id}/post.md does not exist. Call action:'list' to see what does.`);
  }
  return parseFrontmatter(raw);
}

async function writePostDoc(id: string, doc: FmDoc): Promise<void> {
  await gezel.fs.write(`${POSTS_DIR}/${id}/post.md`, serializeFrontmatter(doc));
}

function toIndexEntry(id: string, doc: FmDoc): IndexEntry {
  const entry: IndexEntry = {
    id,
    title: fmGetString(doc, 'title') || id,
    status: fmGetString(doc, 'status') || 'idea',
    platforms: fmGetArray(doc, 'platforms'),
    created: fmGetString(doc, 'created') || today(),
  };
  const scheduledFor = fmGetString(doc, 'scheduledFor');
  if (scheduledFor) entry.scheduledFor = scheduledFor;
  const campaign = fmGetString(doc, 'campaign');
  if (campaign) entry.campaign = campaign;
  return entry;
}

async function regenerateIndex(): Promise<IndexEntry[]> {
  let names: string[] = [];
  try {
    names = (await gezel.fs.list(POSTS_DIR))
      .filter((entry) => entry.isDirectory && entry.name !== '_drafting' && ID_RE.test(entry.name))
      .map((entry) => entry.name);
  } catch {
    names = [];
  }
  const posts: IndexEntry[] = [];
  for (const name of names) {
    try {
      posts.push(toIndexEntry(name, await readPostDoc(name)));
    } catch {
      // A folder without a parseable post.md is not a post; leave it be.
    }
  }
  posts.sort((a, b) => (a.created === b.created ? (a.id < b.id ? 1 : -1) : a.created < b.created ? 1 : -1));
  await gezel.fs.write(INDEX_FILE, `${JSON.stringify({ version: 1, posts }, null, 2)}\n`);
  return posts;
}

async function readIndex(): Promise<IndexEntry[]> {
  try {
    const parsed = JSON.parse(await gezel.fs.read(INDEX_FILE)) as { posts?: IndexEntry[] };
    return Array.isArray(parsed.posts) ? parsed.posts : [];
  } catch {
    return [];
  }
}

async function listVariants(id: string): Promise<Record<string, Record<string, unknown>>> {
  let names: string[] = [];
  try {
    names = (await gezel.fs.list(`${POSTS_DIR}/${id}/variants`))
      .filter((entry) => !entry.isDirectory && entry.name.endsWith('.md'))
      .map((entry) => entry.name);
  } catch {
    return {};
  }
  const variants: Record<string, Record<string, unknown>> = {};
  for (const name of names) {
    const platform = name.slice(0, -3);
    const doc = parseFrontmatter(await gezel.fs.read(`${POSTS_DIR}/${id}/variants/${name}`));
    const body = doc.body.trim();
    const variant: Record<string, unknown> = {
      charCount: Number(fmGetString(doc, 'charCount')) || body.length,
      body,
    };
    for (const key of ['publishedAt', 'permalink', 'postId', 'corpusRef']) {
      const value = fmGetString(doc, key);
      if (value) variant[key] = value;
    }
    variants[platform] = variant;
  }
  return variants;
}

async function listMedia(id: string): Promise<string[]> {
  try {
    return (await gezel.fs.list(`${POSTS_DIR}/${id}/media`))
      .filter((entry) => !entry.isDirectory)
      .map((entry) => entry.name);
  } catch {
    return [];
  }
}

// ── actions ──

if (input.action === 'list') {
  const all = await readIndex();
  let posts = all;
  if (input.status) posts = posts.filter((post) => post.status === input.status);
  if (input.platform) posts = posts.filter((post) => post.platforms.includes(input.platform!));
  const counts = STATUSES.map((status) => {
    const n = all.filter((post) => post.status === status).length;
    return n > 0 ? `${status} ${n}` : null;
  })
    .filter((line) => line !== null)
    .join(', ');
  gezel.output({
    posts,
    total: all.length,
    summary: all.length === 0 ? 'No posts yet — stage one in posts/_drafting/ and call create.' : `${all.length} post(s): ${counts}.`,
  });
} else if (input.action === 'get') {
  const id = requireId();
  const doc = await readPostDoc(id);
  const fields: Record<string, unknown> = {};
  for (const entry of doc.entries) {
    if ('key' in entry) fields[entry.key] = entry.value;
  }
  const post = {
    id,
    ...fields,
    status: fmGetString(doc, 'status') || 'idea',
    platforms: fmGetArray(doc, 'platforms'),
    body: doc.body.trim(),
    variants: await listVariants(id),
    media: await listMedia(id),
  };
  gezel.output({
    post,
    id,
    status: post.status,
    summary: `'${fmGetString(doc, 'title') || id}' is ${post.status}; ${Object.keys(post.variants).length} variant(s), ${post.media.length} media file(s).`,
  });
} else if (input.action === 'create') {
  let staged: FmDoc;
  try {
    staged = parseFrontmatter(await gezel.fs.read(`${DRAFTING}/post.md`));
  } catch {
    throw new Error('Nothing is staged — write posts/_drafting/post.md (frontmatter + body) first, then call create again.');
  }
  const slug = slugify(fmGetString(staged, 'slug') || fmGetString(staged, 'title'));
  if (!slug) throw new Error("The staged post.md needs a 'slug' or a 'title' in its frontmatter to name the post folder.");
  const createdRaw = fmGetString(staged, 'created');
  const created = /^\d{4}-\d{2}-\d{2}$/.test(createdRaw) ? createdRaw : today();
  const id = `${created}-${slug}`;
  if (!ID_RE.test(id)) throw new Error(`Derived post id '${id}' is invalid — keep slug to lowercase letters, digits, and dashes.`);
  const siblings = await gezel.fs.list(POSTS_DIR).catch(() => []);
  if (siblings.some((entry) => entry.name === id)) {
    throw new Error(`posts/${id}/ already exists. Change the staged slug (or created date) and call create again.`);
  }
  const status = input.status ?? 'approved';
  if (!STATUSES.includes(status)) {
    throw new Error(`'${status}' is not a status. Statuses: ${STATUSES.join(', ')}.`);
  }
  fmSet(staged, 'status', status);
  fmSet(staged, 'slug', slug);
  fmSet(staged, 'created', created);
  await gezel.fs.write(`${DRAFTING}/post.md`, serializeFrontmatter(staged));
  await gezel.fs.rename(DRAFTING, `${POSTS_DIR}/${id}`);
  await regenerateIndex();
  gezel.output({
    id,
    status,
    summary: `Committed posts/_drafting/ as posts/${id}/ with status ${status}.`,
  });
} else if (input.action === 'update') {
  const id = requireId();
  const doc = await readPostDoc(id);
  const patches = (input.fields && typeof input.fields === 'object' && !Array.isArray(input.fields) ? input.fields : {}) as Record<string, unknown>;
  let nextStatus = input.status;
  if (typeof patches.status === 'string' && !nextStatus) nextStatus = patches.status;
  delete patches.status;
  if (!nextStatus && Object.keys(patches).length === 0) {
    throw new Error("Nothing to change — pass 'status' and/or a 'fields' object of frontmatter patches.");
  }
  const from = fmGetString(doc, 'status') || 'idea';
  if (nextStatus) assertTransition(id, from, nextStatus);
  for (const [key, value] of Object.entries(patches)) {
    if (value === null || value === undefined) fmDelete(doc, key);
    else if (Array.isArray(value)) fmSet(doc, key, value.map((item) => String(item)));
    else fmSet(doc, key, String(value));
  }
  if (nextStatus) fmSet(doc, 'status', nextStatus);
  await writePostDoc(id, doc);
  await regenerateIndex();
  const status = nextStatus ?? from;
  gezel.output({
    id,
    status,
    summary: nextStatus && nextStatus !== from ? `Moved '${id}' from ${from} to ${status}.` : `Updated '${id}' (${status}).`,
  });
} else if (input.action === 'record_publication') {
  const id = requireId();
  const platform = (input.platform ?? '').trim();
  if (!PLATFORM_RE.test(platform)) {
    throw new Error("Pass 'platform' — the variant that went live, e.g. 'bluesky', 'x', or 'instagram'.");
  }
  const doc = await readPostDoc(id);
  const variantPath = `${POSTS_DIR}/${id}/variants/${platform}.md`;
  const variant = parseFrontmatter(await gezel.fs.read(variantPath).catch(() => '---\n---\n'));
  fmSet(variant, 'publishedAt', input.publishedAt ?? new Date().toISOString());
  if (input.permalink) fmSet(variant, 'permalink', input.permalink);
  if (input.postId) fmSet(variant, 'postId', input.postId);
  if (input.corpusRef) fmSet(variant, 'corpusRef', input.corpusRef);
  await gezel.fs.write(variantPath, serializeFrontmatter(variant));
  const targets = fmGetArray(doc, 'platforms');
  const stamped = await listVariants(id);
  const allLive = targets.length > 0 && targets.every((target) => typeof stamped[target]?.publishedAt === 'string');
  let status = fmGetString(doc, 'status') || 'idea';
  // Recording reality bypasses the stage chain: once every target variant
  // is live (or the caller says so), the post IS published.
  if (allLive || input.markPublished === true) {
    status = 'published';
    fmSet(doc, 'status', status);
    await writePostDoc(id, doc);
  }
  await regenerateIndex();
  const waiting = targets.filter((target) => typeof stamped[target]?.publishedAt !== 'string');
  gezel.output({
    id,
    status,
    summary:
      status === 'published'
        ? `Recorded ${platform} publication for '${id}' — the post is published.`
        : `Recorded ${platform} publication for '${id}'; still waiting on: ${waiting.join(', ') || '(none)'}.`,
  });
} else {
  throw new Error(`Unknown action '${input.action}'. Use list, get, create, update, or record_publication.`);
}

scripts.application-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'application-store',
  description:
    "Read and update the job-search pipeline (applications in pipeline.json, activity in activity.json). Call action:'status' at the start of a session to see where the search stands; 'record_application' the moment the user mentions applying somewhere; 'advance_stage' when reality moves; 'log_activity' for follow-ups, scheduled interviews, and thank-yous.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'record_application', 'advance_stage', or 'log_activity'.",
      required: true,
    },
    company: { type: 'string', description: 'Company name (identifies the application when id is omitted).' },
    role: { type: 'string', description: 'Role title for a new application.' },
    link: { type: 'string', description: 'Posting or application link.' },
    notes: { type: 'string', description: 'Free-form notes for a new application.' },
    id: { type: 'string', description: "Application id (e.g. 'acme-staff-engineer') when advancing or logging." },
    stage: {
      type: 'string',
      description: 'Target stage for advance_stage: applied, screening, interview, offer, or closed.',
    },
    outcome: { type: 'string', description: "With stage 'closed': signed, rejected, or withdrawn." },
    kind: {
      type: 'string',
      description: "Activity kind for log_activity: follow-up, interview-scheduled, thank-you, offer-received, or note.",
    },
    note: { type: 'string', description: 'The activity note for log_activity, or a note on a stage change.' },
    due: { type: 'string', description: 'Due date (ISO) for a follow-up.' },
  },
  outputs: {
    applications: { type: 'number', description: 'Total applications tracked.' },
    summary: { type: 'string', description: 'Human-readable pipeline summary.' },
    stale: { type: 'json', description: 'Active applications untouched for over 7 days.' },
    followUps: { type: 'json', description: 'Follow-ups due within 7 days or overdue.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

const STAGES: [string, ...string[]] = ['applied', 'screening', 'interview', 'offer', 'closed'];
const OUTCOMES = ['signed', 'rejected', 'withdrawn'];
const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

const roster = rosterStore(gezel.fs, 'pipeline.json', { stages: STAGES, idPrefix: 'app' });
const activity = logStore(gezel.fs, 'activity.json');

function slugify(s: string): string {
  return (
    s
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '') || 'application'
  );
}

async function freshId(company: string, role?: string): Promise<string> {
  const base = slugify(role ? `${company} ${role}` : company);
  let candidate = base;
  for (let n = 2; (await roster.get(candidate)) !== null; n += 1) {
    candidate = `${base}-${n}`;
  }
  return candidate;
}

async function resolveId(): Promise<string> {
  if (input.id) {
    if ((await roster.get(input.id)) === null) throw new Error(`No application '${input.id}'.`);
    return input.id;
  }
  if (input.company) {
    const wanted = input.company.toLowerCase();
    const matches = (await roster.list()).filter(
      (r) => String(r.fields.company ?? '').toLowerCase() === wanted,
    );
    if (matches.length === 1) return matches[0]!.id;
    if (matches.length > 1) {
      throw new Error(
        `Multiple applications match company '${input.company}': ${matches.map((m) => m.id).join(', ')}. Pass id.`,
      );
    }
  }
  throw new Error("Pass 'id' or a unique 'company' to identify the application.");
}

async function summarize(): Promise<{
  applications: number;
  summary: string;
  stale: unknown[];
  followUps: unknown[];
}> {
  const records = await roster.list();
  const counts = await roster.counts();
  const now = Date.now();
  const stale = records
    .filter((r) => r.status !== 'closed' && now - Date.parse(r.updatedAt) > WEEK_MS)
    .map((r) => ({
      id: r.id,
      company: r.fields.company ?? r.id,
      stage: r.status,
      daysQuiet: Math.floor((now - Date.parse(r.updatedAt)) / (24 * 60 * 60 * 1000)),
    }));
  const followUps = (await activity.list({ kind: 'follow-up' }))
    .filter((e) => {
      const due = typeof e.data?.dueAt === 'string' ? Date.parse(e.data.dueAt) : null;
      return due !== null && due <= now + WEEK_MS;
    })
    .map((e) => ({
      note: e.note ?? '',
      dueAt: e.data?.dueAt,
      applicationId: e.data?.applicationId,
      overdue: typeof e.data?.dueAt === 'string' && Date.parse(e.data.dueAt) < now,
    }));
  const active = records.filter((r) => r.status !== 'closed').length;
  const stageLine = STAGES.filter((s) => (counts[s] ?? 0) > 0)
    .map((s) => `${s} ${counts[s]}`)
    .join(', ');
  const summary = records.length
    ? `${active} application(s) in play (${stageLine || 'none'}). ${stale.length} stale, ${followUps.length} follow-up(s) due this week.`
    : 'No applications tracked yet.';
  return { applications: records.length, summary, stale, followUps };
}

if (input.action === 'record_application') {
  if (!input.company) throw new Error("record_application needs 'company'.");
  const id = await freshId(input.company, input.role);
  const record = await roster.add({
    id,
    fields: {
      company: input.company,
      ...(input.role ? { role: input.role } : {}),
      ...(input.link ? { link: input.link } : {}),
      ...(input.notes ? { notes: input.notes } : {}),
    },
  });
  await activity.append({
    kind: 'applied',
    note: `Applied to ${input.company}${input.role ? ` for ${input.role}` : ''}.`,
    data: { applicationId: record.id },
  });
} else if (input.action === 'advance_stage') {
  if (!input.stage) throw new Error("advance_stage needs 'stage'.");
  if (!STAGES.includes(input.stage)) {
    throw new Error(`Unknown stage '${input.stage}'. Stages: ${STAGES.join(', ')}.`);
  }
  if (input.outcome && input.stage !== 'closed') {
    throw new Error("'outcome' only applies when closing (stage 'closed').");
  }
  if (input.outcome && !OUTCOMES.includes(input.outcome)) {
    throw new Error(`Unknown outcome '${input.outcome}'. Outcomes: ${OUTCOMES.join(', ')}.`);
  }
  const id = await resolveId();
  await roster.transition(id, input.stage, input.note ? { note: input.note } : {});
  if (input.outcome) await roster.update(id, { fields: { outcome: input.outcome } });
  const company = String((await roster.get(id))?.fields.company ?? id);
  await activity.append({
    kind: 'stage',
    note: `${company} moved to ${input.stage}${input.outcome ? ` (${input.outcome})` : ''}.`,
    data: { applicationId: id },
  });
} else if (input.action === 'log_activity') {
  if (!input.note) throw new Error("log_activity needs 'note'.");
  let applicationId: string | undefined;
  if (input.id || input.company) {
    applicationId = await resolveId();
    // A logged touch counts as attention — it resets the staleness clock.
    await roster.update(applicationId, input.note ? { note: input.note } : {});
  }
  await activity.append({
    kind: input.kind ?? 'note',
    note: input.note,
    data: {
      ...(applicationId ? { applicationId } : {}),
      ...(input.due ? { dueAt: input.due } : {}),
    },
  });
} else if (input.action !== 'status') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, record_application, advance_stage, or log_activity.`,
  );
}

gezel.output(await summarize());

scripts.progress-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'progress-store',
  description:
    "Read and update the student's language-learning progress (level, sessions, streak, notes). Call action:'status' at the start of a session to see where they are; action:'record' after a practice exchange to log it; action:'advance' when they're ready for the next level.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'record', or 'advance'.",
      required: true,
    },
    note: {
      type: 'string',
      description: 'Optional short note to append (what was practiced, a struggle to remember).',
    },
  },
  outputs: {
    level: { type: 'number', description: 'Current level (1+).' },
    sessions: { type: 'number', description: 'Total practice sessions recorded.' },
    streak: { type: 'number', description: 'Consecutive-session streak.' },
    message: { type: 'string', description: 'Human-readable summary of the current state.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

interface Progress {
  language: string;
  level: number;
  sessions: number;
  streak: number;
  notes: string[];
}

async function load(): Promise<Progress> {
  try {
    const raw = await gezel.fs.read('progress.json');
    const p = JSON.parse(raw) as Partial<Progress>;
    return {
      language: p.language ?? 'your language',
      level: p.level ?? 1,
      sessions: p.sessions ?? 0,
      streak: p.streak ?? 0,
      notes: Array.isArray(p.notes) ? p.notes : [],
    };
  } catch {
    return { language: 'your language', level: 1, sessions: 0, streak: 0, notes: [] };
  }
}

const p = await load();
if (input.action === 'record') {
  p.sessions += 1;
  p.streak += 1;
  if (input.note) p.notes.push(input.note);
} else if (input.action === 'advance') {
  p.level += 1;
  p.notes.push(`Advanced to level ${p.level}${input.note ? `: ${input.note}` : ''}`);
}
if (input.action !== 'status') {
  await gezel.fs.write('progress.json', `${JSON.stringify(p, null, 2)}\n`);
}

gezel.output({
  level: p.level,
  sessions: p.sessions,
  streak: p.streak,
  message: `Learning ${p.language}: level ${p.level}, ${p.sessions} session(s), ${p.streak}-session streak.`,
});

scripts.binder-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'binder-store',
  description:
    "Read and update the life binder (documents.json). Call action:'status' for the completeness picture; 'record_document' when a document exists (name + where the original lives); 'mark_missing' / 'mark_reviewed' as reality changes; 'checklist' to read everything.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'record_document', 'mark_missing', 'mark_reviewed', or 'checklist'.",
      required: true,
    },
    name: { type: 'string', description: "Document name, e.g. 'Will', 'Home insurance policy'." },
    location: { type: 'string', description: 'Where the original lives (drawer, safe, provider).' },
    note: { type: 'string', description: 'Anything a trusted person should know about it.' },
    id: { type: 'string', description: "Document id, e.g. 'doc-2'." },
  },
  outputs: {
    total: { type: 'number', description: 'Documents on the checklist.' },
    present: { type: 'number', description: 'Recorded as existing.' },
    missing: { type: 'number', description: 'Known gaps.' },
    stale: { type: 'number', description: 'Present but unreviewed for over a year.' },
    summary: { type: 'string', description: 'The completeness picture.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── binder-rules-start ──
// Pure derivations over rosterStore-shaped document records: statuses are
// missing -> present; staleness is derived (present + unreviewed > 365d).

var YEAR_MS = 365 * 24 * 60 * 60 * 1000;

function isStale(record, nowMs) {
  if (record.status !== 'present') return false;
  var reviewed = record.fields && typeof record.fields.reviewedAt === 'string'
    ? Date.parse(record.fields.reviewedAt)
    : Date.parse(record.updatedAt);
  return isFinite(reviewed) && nowMs - reviewed > YEAR_MS;
}

function binderShape(records, nowMs) {
  var present = 0;
  var missing = [];
  var stale = [];
  records.forEach(function (r) {
    if (r.status === 'present') {
      present += 1;
      if (isStale(r, nowMs)) stale.push(r);
    } else {
      missing.push(r);
    }
  });
  return { present: present, missing: missing, stale: stale };
}

function binderLine(records, nowMs) {
  var shape = binderShape(records, nowMs);
  var gaps = shape.missing
    .map(function (r) {
      return r.fields && r.fields.name ? r.fields.name : r.id;
    })
    .join(', ');
  var staleNames = shape.stale
    .map(function (r) {
      return r.fields && r.fields.name ? r.fields.name : r.id;
    })
    .join(', ');
  return (
    shape.present +
    ' of ' +
    records.length +
    ' in place' +
    (gaps ? '. Missing: ' + gaps : '. Nothing missing') +
    (staleNames ? '. Due a review: ' + staleNames + '.' : '.')
  );
}
// ── binder-rules-end ──

const binder = rosterStore(gezel.fs, 'documents.json', {
  stages: ['missing', 'present'],
  idPrefix: 'doc',
});

async function resolveDoc(): Promise<string> {
  if (input.id) return input.id;
  if (input.name) {
    const wanted = input.name.toLowerCase();
    const matches = (await binder.list()).filter(
      (r) => String(r.fields.name ?? '').toLowerCase() === wanted,
    );
    if (matches.length === 1) return matches[0]!.id;
  }
  throw new Error("Pass 'id' (e.g. 'doc-2') or an exact document 'name'.");
}

if (input.action === 'record_document') {
  if (!input.name) throw new Error("record_document needs 'name'.");
  const existing = (await binder.list()).find(
    (r) => String(r.fields.name ?? '').toLowerCase() === input.name!.toLowerCase(),
  );
  if (existing) {
    await binder.update(existing.id, {
      fields: {
        ...(input.location ? { location: input.location } : {}),
        ...(input.note ? { note: input.note } : {}),
        reviewedAt: new Date().toISOString(),
      },
    });
    await binder.transition(existing.id, 'present');
  } else {
    await binder.add({
      status: 'present',
      fields: {
        name: input.name,
        ...(input.location ? { location: input.location } : {}),
        ...(input.note ? { note: input.note } : {}),
        reviewedAt: new Date().toISOString(),
      },
    });
  }
} else if (input.action === 'mark_missing') {
  await binder.transition(await resolveDoc(), 'missing');
} else if (input.action === 'mark_reviewed') {
  const id = await resolveDoc();
  await binder.update(id, { fields: { reviewedAt: new Date().toISOString() } });
  await binder.transition(id, 'present');
} else if (input.action !== 'status' && input.action !== 'checklist') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, record_document, mark_missing, mark_reviewed, or checklist.`,
  );
}

const records = await binder.list();
const shape = binderShape(records, Date.now());
const listing =
  input.action === 'checklist'
    ? records
        .map(
          (r) =>
            `${r.id} [${r.status}${isStale(r, Date.now()) ? ', stale' : ''}] ${String(r.fields.name ?? '?')}${r.fields.location ? ` — ${String(r.fields.location)}` : ''}`,
        )
        .join('\n') || 'The checklist is empty.'
    : '';

gezel.output({
  total: records.length,
  present: shape.present,
  missing: shape.missing.length,
  stale: shape.stale.length,
  summary: listing || binderLine(records, Date.now()),
});

scripts.kitchen-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'kitchen-store',
  description:
    "Read and update the week's menu (menu.json) and the pantry (pantry.json). Call action:'status' for today's dinner + the grocery gap; 'set_menu' day by day; 'pantry_add' / 'pantry_level' as staples change; 'grocery_list' for the run.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'set_menu', 'pantry_add', 'pantry_level', or 'grocery_list'.",
      required: true,
    },
    day: {
      type: 'string',
      description: "Day for set_menu: monday..sunday.",
    },
    meal: { type: 'string', description: 'The dinner for that day.' },
    name: { type: 'string', description: 'Pantry item name.' },
    level: { type: 'string', description: "Pantry level: 'stocked', 'low', or 'out'." },
    id: { type: 'string', description: "Pantry item id, e.g. 'item-3'." },
  },
  outputs: {
    planned: { type: 'number', description: 'Days with a planned dinner.' },
    groceries: { type: 'number', description: 'Items on the grocery list.' },
    summary: { type: 'string', description: 'The kitchen picture.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── kitchen-rules-start ──
// Pure derivations: the weekly menu shape and the grocery gap (pantry
// items marked low or out).

var DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];

function normalizeDay(day) {
  if (typeof day !== 'string') return null;
  var d = day.toLowerCase();
  return DAYS.indexOf(d) >= 0 ? d : null;
}

function todayName(nowMs) {
  // getUTCDay: 0=Sunday.
  var idx = new Date(nowMs).getUTCDay();
  return DAYS[(idx + 6) % 7];
}

function groceryGap(records) {
  return records.filter(function (r) {
    return r.status === 'low' || r.status === 'out';
  });
}

function kitchenLine(menu, records, nowMs) {
  var today = todayName(nowMs);
  var tonight = menu.days && menu.days[today];
  var gap = groceryGap(records);
  var planned = DAYS.filter(function (d) {
    return menu.days && menu.days[d];
  }).length;
  return (
    (tonight ? "Tonight: " + tonight + '.' : 'Nothing planned for tonight.') +
    ' ' +
    planned +
    ' of 7 dinners planned. Grocery list: ' +
    (gap.length
      ? gap
          .map(function (r) {
            return (r.fields && r.fields.name) || r.id;
          })
          .join(', ')
      : 'empty')
  );
}
// ── kitchen-rules-end ──

const MENU_FILE = 'menu.json';
const pantry = rosterStore(gezel.fs, 'pantry.json', {
  stages: ['stocked', 'low', 'out'],
  idPrefix: 'item',
});

interface Menu {
  version: number;
  days: Record<string, string>;
  updatedAt: string;
}

async function loadMenu(): Promise<Menu> {
  try {
    const parsed = JSON.parse(await gezel.fs.read(MENU_FILE)) as Partial<Menu>;
    return {
      version: 1,
      days: parsed.days && typeof parsed.days === 'object' ? (parsed.days as Record<string, string>) : {},
      updatedAt: new Date().toISOString(),
    };
  } catch {
    return { version: 1, days: {}, updatedAt: new Date().toISOString() };
  }
}

async function saveMenu(menu: Menu): Promise<void> {
  menu.updatedAt = new Date().toISOString();
  await gezel.fs.write(MENU_FILE, `${JSON.stringify(menu, null, 2)}\n`);
}

async function resolveItem(): Promise<string> {
  if (input.id) return input.id;
  if (input.name) {
    const wanted = input.name.toLowerCase();
    const matches = (await pantry.list()).filter(
      (r) => String(r.fields.name ?? '').toLowerCase() === wanted,
    );
    if (matches.length === 1) return matches[0]!.id;
  }
  throw new Error("Pass 'id' (e.g. 'item-3') or an exact pantry item 'name'.");
}

const menu = await loadMenu();

if (input.action === 'set_menu') {
  const day = normalizeDay(input.day);
  if (!day || !input.meal) throw new Error("set_menu needs 'day' (monday..sunday) and 'meal'.");
  menu.days[day] = input.meal;
  await saveMenu(menu);
} else if (input.action === 'pantry_add') {
  if (!input.name) throw new Error("pantry_add needs 'name'.");
  const level = input.level && ['stocked', 'low', 'out'].includes(input.level) ? input.level : 'stocked';
  await pantry.add({ status: level, fields: { name: input.name } });
} else if (input.action === 'pantry_level') {
  if (!input.level || !['stocked', 'low', 'out'].includes(input.level)) {
    throw new Error("pantry_level needs level 'stocked', 'low', or 'out'.");
  }
  await pantry.transition(await resolveItem(), input.level);
} else if (input.action !== 'status' && input.action !== 'grocery_list') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, set_menu, pantry_add, pantry_level, or grocery_list.`,
  );
}

const records = await pantry.list();
const gap = groceryGap(records);
const listing =
  input.action === 'grocery_list'
    ? gap
        .map((r) => `${String(r.fields.name ?? r.id)} (${r.status})`)
        .join('\n') || 'The grocery list is empty.'
    : '';

gezel.output({
  planned: DAYS.filter((d) => menu.days[d]).length,
  groceries: gap.length,
  summary: listing || kitchenLine(menu, records, Date.now()),
});

scripts.manuscript-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'manuscript-store',
  description:
    "Read and update the manuscript record (sessions.json + chapters.json). Call action:'status' for total words, weekly pace, and the chapter board; 'log_session' after every writing session (words written); 'add_chapter' / 'chapter_stage' to keep the board honest; 'outline' to list every chapter.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'log_session', 'add_chapter', 'chapter_stage', or 'outline'.",
      required: true,
    },
    words: { type: 'number', description: 'Words written this session (log_session).' },
    note: { type: 'string', description: 'Anything worth remembering.' },
    title: { type: 'string', description: 'Chapter title (add_chapter).' },
    summary: { type: 'string', description: 'One-line chapter summary (add_chapter).' },
    id: { type: 'string', description: "Chapter id, e.g. 'ch-3' (chapter_stage)." },
    stage: {
      type: 'string',
      description: "Target stage: 'outline', 'drafting', 'revised', or 'done' (chapter_stage).",
    },
  },
  outputs: {
    totalWords: { type: 'number', description: 'Words logged across all sessions.' },
    thisWeekWords: { type: 'number', description: 'Words logged this week (Monday UTC start).' },
    chapters: { type: 'number', description: 'Chapters on the board.' },
    summary: { type: 'string', description: 'The manuscript picture.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── novel-rules-start ──
// Pure derivations over logStore-shaped writing sessions (kind 'writing',
// data {words}) and rosterStore-shaped chapters (stages outline → drafting
// → revised → done). Weeks start Monday 00:00 UTC; nowIso is a parameter
// so the rules stay clock-independent and testable.

function sessionWords(e) {
  var words = e && e.data ? Number(e.data.words) : NaN;
  return isFinite(words) && words > 0 ? Math.round(words) : 0;
}

function totalWords(events) {
  return events.reduce(function (sum, e) {
    return sum + sessionWords(e);
  }, 0);
}

function weekStartMs(nowIso) {
  var day = new Date(nowIso.slice(0, 10) + 'T00:00:00Z');
  var sinceMonday = (day.getUTCDay() + 6) % 7;
  return day.getTime() - sinceMonday * 86400000;
}

function thisWeekWords(events, nowIso) {
  var start = weekStartMs(nowIso);
  return totalWords(
    events.filter(function (e) {
      return Date.parse(e.at) >= start;
    }),
  );
}

function chapterShape(records) {
  var byStage = { outline: 0, drafting: 0, revised: 0, done: 0 };
  records.forEach(function (r) {
    if (byStage[r.status] !== undefined) byStage[r.status] += 1;
  });
  return byStage;
}

function novelLine(events, records, nowIso, weeklyWordGoal) {
  var total = totalWords(events);
  var week = thisWeekWords(events, nowIso);
  var shape = chapterShape(records);
  var goal = weeklyWordGoal > 0 ? weeklyWordGoal : 0;
  return (
    total +
    ' words logged; ' +
    week +
    (goal > 0 ? ' of ' + goal : '') +
    ' this week. Chapters: ' +
    shape.outline +
    ' outlined, ' +
    shape.drafting +
    ' drafting, ' +
    shape.revised +
    ' revised, ' +
    shape.done +
    ' done.'
  );
}
// ── novel-rules-end ──

const sessions = logStore(gezel.fs, 'sessions.json');
const chapters = rosterStore(gezel.fs, 'chapters.json', {
  stages: ['outline', 'drafting', 'revised', 'done'],
  idPrefix: 'ch',
});

async function readWeeklyWordGoal(): Promise<number> {
  try {
    const parsed = JSON.parse(await gezel.fs.read('sessions.json')) as { weeklyWordGoal?: unknown };
    const goal = Number(parsed.weeklyWordGoal);
    return Number.isFinite(goal) && goal > 0 ? Math.round(goal) : 0;
  } catch {
    return 0;
  }
}

if (input.action === 'log_session') {
  const words = Number(input.words);
  if (!Number.isFinite(words) || words <= 0) {
    throw new Error("log_session needs a positive 'words' count.");
  }
  await sessions.append({
    kind: 'writing',
    ...(input.note ? { note: input.note } : {}),
    data: { words: Math.round(words) },
  });
} else if (input.action === 'add_chapter') {
  if (!input.title) throw new Error("add_chapter needs a 'title'.");
  await chapters.add({
    fields: { title: input.title, ...(input.summary ? { summary: input.summary } : {}) },
    ...(input.note ? { note: input.note } : {}),
  });
} else if (input.action === 'chapter_stage') {
  if (!input.id || !input.stage) {
    throw new Error("chapter_stage needs 'id' (e.g. 'ch-3') and 'stage'.");
  }
  await chapters.transition(input.id, input.stage, input.note ? { note: input.note } : undefined);
} else if (input.action !== 'status' && input.action !== 'outline') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, log_session, add_chapter, chapter_stage, or outline.`,
  );
}

const events = await sessions.list();
const records = await chapters.list();
const weeklyWordGoal = await readWeeklyWordGoal();
const nowIso = new Date().toISOString();
const listing =
  input.action === 'outline'
    ? records
        .map(
          (r) =>
            `${r.id} [${r.status}] ${String(r.fields.title ?? '')}${r.fields.summary ? ` — ${String(r.fields.summary)}` : ''}`,
        )
        .join('\n') || 'No chapters on the board yet.'
    : '';

gezel.output({
  totalWords: totalWords(events),
  thisWeekWords: thisWeekWords(events, nowIso),
  chapters: records.length,
  summary: listing || novelLine(events, records, nowIso, weeklyWordGoal),
});

scripts.posts-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'posts-store',
  description:
    "Read and update the post pipeline under posts/. Call action:'list' to see every post (optional status/platform filters); 'get' for one post's frontmatter, body, variants, and media; 'create' to commit the staged posts/_drafting/ folder as a real post; 'update' to patch frontmatter or move a post one pipeline stage (idea, draft, in-review, approved, scheduled, published, archived from anywhere); 'record_publication' to stamp a platform variant with its permalink after it goes live. Illegal stage jumps fail with the legal next stages — move one stage at a time.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'list', 'get', 'create', 'update', or 'record_publication'.",
      required: true,
    },
    id: { type: 'string', description: "Post id — its folder name under posts/, e.g. '2026-08-12-launch-teaser'." },
    status: {
      type: 'string',
      description: "Target status: idea, draft, in-review, approved, scheduled, published, or archived. For 'create', the initial status (defaults to approved).",
    },
    platform: { type: 'string', description: "Platform filter for 'list', or the published variant for 'record_publication' (e.g. 'bluesky')." },
    fields: {
      type: 'json',
      description: "For 'update': an object of frontmatter patches, e.g. {\"scheduledFor\": \"2026-08-15T09:00:00Z\", \"campaign\": \"autumn\"}. A null value clears the key.",
    },
    permalink: { type: 'string', description: 'Public URL of the live post, for record_publication.' },
    postId: { type: 'string', description: "The platform's own id for the live post, for record_publication." },
    corpusRef: { type: 'string', description: 'Connector corpus record reference for the live post, when one exists.' },
    publishedAt: { type: 'string', description: 'ISO timestamp the post went live (defaults to now).' },
    markPublished: {
      type: 'boolean',
      description: 'For record_publication: force the post to published even if other target platforms are not stamped yet.',
    },
  },
  outputs: {
    posts: { type: 'json', description: "For 'list': the post listing entries." },
    total: { type: 'number', description: "For 'list': how many posts exist before filtering." },
    post: { type: 'json', description: "For 'get': frontmatter plus body, variants map, and media names." },
    id: { type: 'string', description: 'The post id the action touched.' },
    status: { type: 'string', description: "The post's status after the action." },
    summary: { type: 'string', description: 'Human-readable result.' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

const POSTS_DIR = 'posts';
const DRAFTING = 'posts/_drafting';
const INDEX_FILE = 'posts/index.json';
const ID_RE = /^[a-z0-9][a-z0-9-]{0,99}$/;
const PLATFORM_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;
const STAGES = ['idea', 'draft', 'in-review', 'approved', 'scheduled', 'published'] as const;
const STATUSES: string[] = [...STAGES, 'archived'];

// ── frontmatter ──
// Hand-rolled, deliberately simple: `---`-delimited `key: value` lines,
// arrays as [a, b]. Unknown keys and even unparseable lines are preserved
// in order so a round-trip never loses what a human or another tool wrote.

type FmEntry = { key: string; value: string | string[] } | { raw: string };
interface FmDoc {
  entries: FmEntry[];
  body: string;
}

function parseArrayish(value: string): string[] {
  return value
    .slice(1, -1)
    .split(',')
    .map((part) => part.trim().replace(/^["']|["']$/g, ''))
    .filter((part) => part.length > 0);
}

function parseFrontmatter(text: string): FmDoc {
  const lines = text.split(/\r?\n/);
  if (lines[0]?.trim() !== '---') return { entries: [], body: text };
  const entries: FmEntry[] = [];
  let at = 1;
  for (; at < lines.length; at += 1) {
    const line = lines[at]!;
    if (line.trim() === '---') {
      return { entries, body: lines.slice(at + 1).join('\n').replace(/^\n/, '') };
    }
    const sep = line.indexOf(':');
    if (sep <= 0) {
      if (line.trim().length > 0) entries.push({ raw: line });
      continue;
    }
    const key = line.slice(0, sep).trim();
    const value = line.slice(sep + 1).trim();
    if (!key) {
      entries.push({ raw: line });
      continue;
    }
    entries.push({
      key,
      value: value.startsWith('[') && value.endsWith(']') ? parseArrayish(value) : value,
    });
  }
  return { entries: [], body: text };
}

function serializeFrontmatter(doc: FmDoc): string {
  const lines = doc.entries.map((entry) => {
    if ('raw' in entry) return entry.raw;
    const value = Array.isArray(entry.value) ? `[${entry.value.join(', ')}]` : entry.value;
    return `${entry.key}: ${value}`;
  });
  return `---\n${lines.join('\n')}\n---\n\n${doc.body.replace(/^\n+/, '')}`;
}

function fmGet(doc: FmDoc, key: string): string | string[] | undefined {
  for (const entry of doc.entries) {
    if ('key' in entry && entry.key === key) return entry.value;
  }
  return undefined;
}

function fmGetString(doc: FmDoc, key: string): string {
  const value = fmGet(doc, key);
  if (Array.isArray(value)) return value.join(', ');
  return value ?? '';
}

function fmGetArray(doc: FmDoc, key: string): string[] {
  const value = fmGet(doc, key);
  if (Array.isArray(value)) return value;
  if (typeof value === 'string' && value.length > 0) return [value];
  return [];
}

function fmSet(doc: FmDoc, key: string, value: string | string[]): void {
  for (const entry of doc.entries) {
    if ('key' in entry && entry.key === key) {
      entry.value = value;
      return;
    }
  }
  doc.entries.push({ key, value });
}

function fmDelete(doc: FmDoc, key: string): void {
  doc.entries = doc.entries.filter((entry) => !('key' in entry && entry.key === key));
}

// ── pipeline rules ──

function legalNext(from: string): string[] {
  if (from === 'archived') return [];
  const at = STAGES.indexOf(from as (typeof STAGES)[number]);
  const forward = at >= 0 && at < STAGES.length - 1 ? [STAGES[at + 1]!] : [];
  return [...forward, 'archived'];
}

function assertTransition(id: string, from: string, to: string): void {
  if (to === from) return;
  if (!STATUSES.includes(to)) {
    throw new Error(`Unknown status '${to}'. Statuses: ${STATUSES.join(', ')}.`);
  }
  if (!legalNext(from).includes(to)) {
    const next = legalNext(from);
    throw new Error(
      `Cannot move '${id}' from ${from} to ${to} — posts move one stage at a time. ` +
        (next.length > 0 ? `Legal next: ${next.join(', ')}.` : `'${from}' is final; create a new post instead.`),
    );
  }
}

function requireId(): string {
  const id = (input.id ?? '').trim();
  if (!id) throw new Error("Pass 'id' — the post's folder name under posts/ (see action:'list').");
  if (!ID_RE.test(id)) {
    throw new Error(`Invalid post id '${id}'. Ids are lowercase [a-z0-9-], no slashes or dots.`);
  }
  return id;
}

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
}

// ── store ──

interface IndexEntry {
  id: string;
  title: string;
  status: string;
  platforms: string[];
  created: string;
  scheduledFor?: string;
  campaign?: string;
}

async function readPostDoc(id: string): Promise<FmDoc> {
  let raw: string;
  try {
    raw = await gezel.fs.read(`${POSTS_DIR}/${id}/post.md`);
  } catch {
    throw new Error(`No post '${id}' — posts/${id}/post.md does not exist. Call action:'list' to see what does.`);
  }
  return parseFrontmatter(raw);
}

async function writePostDoc(id: string, doc: FmDoc): Promise<void> {
  await gezel.fs.write(`${POSTS_DIR}/${id}/post.md`, serializeFrontmatter(doc));
}

function toIndexEntry(id: string, doc: FmDoc): IndexEntry {
  const entry: IndexEntry = {
    id,
    title: fmGetString(doc, 'title') || id,
    status: fmGetString(doc, 'status') || 'idea',
    platforms: fmGetArray(doc, 'platforms'),
    created: fmGetString(doc, 'created') || today(),
  };
  const scheduledFor = fmGetString(doc, 'scheduledFor');
  if (scheduledFor) entry.scheduledFor = scheduledFor;
  const campaign = fmGetString(doc, 'campaign');
  if (campaign) entry.campaign = campaign;
  return entry;
}

async function regenerateIndex(): Promise<IndexEntry[]> {
  let names: string[] = [];
  try {
    names = (await gezel.fs.list(POSTS_DIR))
      .filter((entry) => entry.isDirectory && entry.name !== '_drafting' && ID_RE.test(entry.name))
      .map((entry) => entry.name);
  } catch {
    names = [];
  }
  const posts: IndexEntry[] = [];
  for (const name of names) {
    try {
      posts.push(toIndexEntry(name, await readPostDoc(name)));
    } catch {
      // A folder without a parseable post.md is not a post; leave it be.
    }
  }
  posts.sort((a, b) => (a.created === b.created ? (a.id < b.id ? 1 : -1) : a.created < b.created ? 1 : -1));
  await gezel.fs.write(INDEX_FILE, `${JSON.stringify({ version: 1, posts }, null, 2)}\n`);
  return posts;
}

async function readIndex(): Promise<IndexEntry[]> {
  try {
    const parsed = JSON.parse(await gezel.fs.read(INDEX_FILE)) as { posts?: IndexEntry[] };
    return Array.isArray(parsed.posts) ? parsed.posts : [];
  } catch {
    return [];
  }
}

async function listVariants(id: string): Promise<Record<string, Record<string, unknown>>> {
  let names: string[] = [];
  try {
    names = (await gezel.fs.list(`${POSTS_DIR}/${id}/variants`))
      .filter((entry) => !entry.isDirectory && entry.name.endsWith('.md'))
      .map((entry) => entry.name);
  } catch {
    return {};
  }
  const variants: Record<string, Record<string, unknown>> = {};
  for (const name of names) {
    const platform = name.slice(0, -3);
    const doc = parseFrontmatter(await gezel.fs.read(`${POSTS_DIR}/${id}/variants/${name}`));
    const body = doc.body.trim();
    const variant: Record<string, unknown> = {
      charCount: Number(fmGetString(doc, 'charCount')) || body.length,
      body,
    };
    for (const key of ['publishedAt', 'permalink', 'postId', 'corpusRef']) {
      const value = fmGetString(doc, key);
      if (value) variant[key] = value;
    }
    variants[platform] = variant;
  }
  return variants;
}

async function listMedia(id: string): Promise<string[]> {
  try {
    return (await gezel.fs.list(`${POSTS_DIR}/${id}/media`))
      .filter((entry) => !entry.isDirectory)
      .map((entry) => entry.name);
  } catch {
    return [];
  }
}

// ── actions ──

if (input.action === 'list') {
  const all = await readIndex();
  let posts = all;
  if (input.status) posts = posts.filter((post) => post.status === input.status);
  if (input.platform) posts = posts.filter((post) => post.platforms.includes(input.platform!));
  const counts = STATUSES.map((status) => {
    const n = all.filter((post) => post.status === status).length;
    return n > 0 ? `${status} ${n}` : null;
  })
    .filter((line) => line !== null)
    .join(', ');
  gezel.output({
    posts,
    total: all.length,
    summary: all.length === 0 ? 'No posts yet — stage one in posts/_drafting/ and call create.' : `${all.length} post(s): ${counts}.`,
  });
} else if (input.action === 'get') {
  const id = requireId();
  const doc = await readPostDoc(id);
  const fields: Record<string, unknown> = {};
  for (const entry of doc.entries) {
    if ('key' in entry) fields[entry.key] = entry.value;
  }
  const post = {
    id,
    ...fields,
    status: fmGetString(doc, 'status') || 'idea',
    platforms: fmGetArray(doc, 'platforms'),
    body: doc.body.trim(),
    variants: await listVariants(id),
    media: await listMedia(id),
  };
  gezel.output({
    post,
    id,
    status: post.status,
    summary: `'${fmGetString(doc, 'title') || id}' is ${post.status}; ${Object.keys(post.variants).length} variant(s), ${post.media.length} media file(s).`,
  });
} else if (input.action === 'create') {
  let staged: FmDoc;
  try {
    staged = parseFrontmatter(await gezel.fs.read(`${DRAFTING}/post.md`));
  } catch {
    throw new Error('Nothing is staged — write posts/_drafting/post.md (frontmatter + body) first, then call create again.');
  }
  const slug = slugify(fmGetString(staged, 'slug') || fmGetString(staged, 'title'));
  if (!slug) throw new Error("The staged post.md needs a 'slug' or a 'title' in its frontmatter to name the post folder.");
  const createdRaw = fmGetString(staged, 'created');
  const created = /^\d{4}-\d{2}-\d{2}$/.test(createdRaw) ? createdRaw : today();
  const id = `${created}-${slug}`;
  if (!ID_RE.test(id)) throw new Error(`Derived post id '${id}' is invalid — keep slug to lowercase letters, digits, and dashes.`);
  const siblings = await gezel.fs.list(POSTS_DIR).catch(() => []);
  if (siblings.some((entry) => entry.name === id)) {
    throw new Error(`posts/${id}/ already exists. Change the staged slug (or created date) and call create again.`);
  }
  const status = input.status ?? 'approved';
  if (!STATUSES.includes(status)) {
    throw new Error(`'${status}' is not a status. Statuses: ${STATUSES.join(', ')}.`);
  }
  fmSet(staged, 'status', status);
  fmSet(staged, 'slug', slug);
  fmSet(staged, 'created', created);
  await gezel.fs.write(`${DRAFTING}/post.md`, serializeFrontmatter(staged));
  await gezel.fs.rename(DRAFTING, `${POSTS_DIR}/${id}`);
  await regenerateIndex();
  gezel.output({
    id,
    status,
    summary: `Committed posts/_drafting/ as posts/${id}/ with status ${status}.`,
  });
} else if (input.action === 'update') {
  const id = requireId();
  const doc = await readPostDoc(id);
  const patches = (input.fields && typeof input.fields === 'object' && !Array.isArray(input.fields) ? input.fields : {}) as Record<string, unknown>;
  let nextStatus = input.status;
  if (typeof patches.status === 'string' && !nextStatus) nextStatus = patches.status;
  delete patches.status;
  if (!nextStatus && Object.keys(patches).length === 0) {
    throw new Error("Nothing to change — pass 'status' and/or a 'fields' object of frontmatter patches.");
  }
  const from = fmGetString(doc, 'status') || 'idea';
  if (nextStatus) assertTransition(id, from, nextStatus);
  for (const [key, value] of Object.entries(patches)) {
    if (value === null || value === undefined) fmDelete(doc, key);
    else if (Array.isArray(value)) fmSet(doc, key, value.map((item) => String(item)));
    else fmSet(doc, key, String(value));
  }
  if (nextStatus) fmSet(doc, 'status', nextStatus);
  await writePostDoc(id, doc);
  await regenerateIndex();
  const status = nextStatus ?? from;
  gezel.output({
    id,
    status,
    summary: nextStatus && nextStatus !== from ? `Moved '${id}' from ${from} to ${status}.` : `Updated '${id}' (${status}).`,
  });
} else if (input.action === 'record_publication') {
  const id = requireId();
  const platform = (input.platform ?? '').trim();
  if (!PLATFORM_RE.test(platform)) {
    throw new Error("Pass 'platform' — the variant that went live, e.g. 'bluesky', 'x', or 'instagram'.");
  }
  const doc = await readPostDoc(id);
  const variantPath = `${POSTS_DIR}/${id}/variants/${platform}.md`;
  const variant = parseFrontmatter(await gezel.fs.read(variantPath).catch(() => '---\n---\n'));
  fmSet(variant, 'publishedAt', input.publishedAt ?? new Date().toISOString());
  if (input.permalink) fmSet(variant, 'permalink', input.permalink);
  if (input.postId) fmSet(variant, 'postId', input.postId);
  if (input.corpusRef) fmSet(variant, 'corpusRef', input.corpusRef);
  await gezel.fs.write(variantPath, serializeFrontmatter(variant));
  const targets = fmGetArray(doc, 'platforms');
  const stamped = await listVariants(id);
  const allLive = targets.length > 0 && targets.every((target) => typeof stamped[target]?.publishedAt === 'string');
  let status = fmGetString(doc, 'status') || 'idea';
  // Recording reality bypasses the stage chain: once every target variant
  // is live (or the caller says so), the post IS published.
  if (allLive || input.markPublished === true) {
    status = 'published';
    fmSet(doc, 'status', status);
    await writePostDoc(id, doc);
  }
  await regenerateIndex();
  const waiting = targets.filter((target) => typeof stamped[target]?.publishedAt !== 'string');
  gezel.output({
    id,
    status,
    summary:
      status === 'published'
        ? `Recorded ${platform} publication for '${id}' — the post is published.`
        : `Recorded ${platform} publication for '${id}'; still waiting on: ${waiting.join(', ') || '(none)'}.`,
  });
} else {
  throw new Error(`Unknown action '${input.action}'. Use list, get, create, update, or record_publication.`);
}

scripts.trip-store:
import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'trip-store',
  description:
    "Read and update the trip: itinerary + packing (trip.json) and the journal (journal.json). Call action:'status' for the shape of the trip; 'plan_day' with date + plan; 'pack_add' / 'pack_check' for the packing list; 'journal_entry' during the trip.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'plan_day', 'pack_add', 'pack_check', 'journal_entry', or 'itinerary'.",
      required: true,
    },
    date: { type: 'string', description: 'Day being planned, e.g. 2026-09-14.' },
    plan: { type: 'string', description: "The day's plan (anchor + options)." },
    item: { type: 'string', description: 'Packing item name.' },
    id: { type: 'string', description: "Packing item id, e.g. 'pack-3'." },
    note: { type: 'string', description: 'Journal entry text.' },
  },
  outputs: {
    daysPlanned: { type: 'number', description: 'Days with a plan.' },
    unpacked: { type: 'number', description: 'Packing items still unpacked.' },
    summary: { type: 'string', description: 'The trip picture (or the itinerary).' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── trip-rules-start ──
// Pure derivations over the trip doc: countdown and itinerary rendering.

function daysUntil(dateStr, nowMs) {
  var when = Date.parse(dateStr);
  if (!isFinite(when)) return null;
  return Math.ceil((when - nowMs) / (24 * 60 * 60 * 1000));
}

function renderItinerary(days) {
  var dates = Object.keys(days).sort();
  if (dates.length === 0) return 'No days planned yet.';
  return dates
    .map(function (d) {
      return d + ': ' + days[d];
    })
    .join('\n');
}

function tripLine(trip, unpackedCount, nowMs) {
  var start = daysUntil(trip.startDate, nowMs);
  var planned = Object.keys(trip.days || {}).length;
  var lead =
    start === null
      ? ''
      : start > 0
        ? start + ' day(s) until departure. '
        : start === 0
          ? 'Departure day! '
          : 'On the road (or home again). ';
  return (
    lead + planned + ' day(s) planned. Packing: ' +
    (unpackedCount === 0 ? 'all packed.' : unpackedCount + ' item(s) still unpacked.')
  );
}
// ── trip-rules-end ──

const TRIP_FILE = 'trip.json';
const packing = rosterStore(gezel.fs, 'packing.json', {
  stages: ['unpacked', 'packed'],
  idPrefix: 'pack',
});
const journal = logStore(gezel.fs, 'journal.json');

interface Trip {
  version: number;
  destination: string;
  startDate: string;
  days: Record<string, string>;
  updatedAt: string;
}

async function loadTrip(): Promise<Trip> {
  try {
    const parsed = JSON.parse(await gezel.fs.read(TRIP_FILE)) as Partial<Trip>;
    return {
      version: 1,
      destination: typeof parsed.destination === 'string' ? parsed.destination : '',
      startDate: typeof parsed.startDate === 'string' ? parsed.startDate : '',
      days: parsed.days && typeof parsed.days === 'object' ? (parsed.days as Record<string, string>) : {},
      updatedAt: new Date().toISOString(),
    };
  } catch {
    return { version: 1, destination: '', startDate: '', days: {}, updatedAt: new Date().toISOString() };
  }
}

async function saveTrip(trip: Trip): Promise<void> {
  trip.updatedAt = new Date().toISOString();
  await gezel.fs.write(TRIP_FILE, `${JSON.stringify(trip, null, 2)}\n`);
}

const trip = await loadTrip();

if (input.action === 'plan_day') {
  if (!input.date || !input.plan) throw new Error("plan_day needs 'date' (YYYY-MM-DD) and 'plan'.");
  trip.days[input.date.slice(0, 10)] = input.plan;
  await saveTrip(trip);
} else if (input.action === 'pack_add') {
  if (!input.item) throw new Error("pack_add needs 'item'.");
  await packing.add({ status: 'unpacked', fields: { name: input.item } });
} else if (input.action === 'pack_check') {
  let id = input.id;
  if (!id && input.item) {
    const wanted = input.item.toLowerCase();
    const matches = (await packing.list()).filter(
      (r) => String(r.fields.name ?? '').toLowerCase() === wanted,
    );
    if (matches.length === 1) id = matches[0]!.id;
  }
  if (!id) throw new Error("Pass 'id' (e.g. 'pack-3') or an exact packing 'item'.");
  await packing.transition(id, 'packed');
} else if (input.action === 'journal_entry') {
  if (!input.note) throw new Error("journal_entry needs 'note'.");
  await journal.append({ kind: 'entry', note: input.note });
} else if (input.action !== 'status' && input.action !== 'itinerary') {
  throw new Error(
    `Unknown action '${input.action}'. Use status, plan_day, pack_add, pack_check, journal_entry, or itinerary.`,
  );
}

const packItems = await packing.list();
const unpacked = packItems.filter((r) => r.status === 'unpacked').length;

gezel.output({
  daysPlanned: Object.keys(trip.days).length,
  unpacked,
  summary:
    input.action === 'itinerary' ? renderItinerary(trip.days) : tripLine(trip, unpacked, Date.now()),
});
